window.HERO_GUIDE=[{"id":1,"en":"Infernus","ko":"인페르누스","aliases":["인페르누스","Infernus","인퍼너스"],"role":"marksman","complexity":1,"style":"총알로 화상을 쌓아 지속 피해로 녹이는 기동형 딜러","tags":["지속 피해","기동","광역 기절"],"laneStrength":"strong","spikes":"화염 흔적과 네이팜 덕분에 초반부터 견제가 강합니다. 충격 폭발을 배우면 한타 진입력이 생기고, 지속 시간·탄창 아이템이 갖춰질수록 교전 딜이 크게 오릅니다.","strengths":["총알마다 화상이 쌓여 짧은 교전에 강함","화염 대시로 진입과 도주가 모두 쉬움","궁극기로 여러 명을 한 번에 기절시킴"],"weaknesses":["사거리가 짧아 장거리 견제에 약함","화염 대시가 빠지면 도망치기 어려움","궁극기 폭발까지 지연이 있어 피할 수 있음"],"vsTips":["네이팜에 맞으면 바로 뒤로 빠져 화상 연장을 끊으세요","충격 폭발 시전이 보이면 즉시 반경 밖으로 대시하세요","화염 대시를 쓴 직후 빠질 수단이 없을 때 반격하세요"],"withTips":["상대를 묶어 주면 인페르누스가 화상을 쌓기 쉬워집니다","궁극기가 터지는 순간 함께 들어가 기절한 적을 마무리하세요"],"plan":{"early":"화염 흔적으로 상대 체력을 깎고 네이팜으로 웨이브를 정리하세요.","mid":"화염 대시로 옆 전선을 돌며 갱킹과 정글 파밍을 병행하세요.","late":"측면에서 화염 대시로 파고들어 충격 폭발로 한타를 여세요."},"core":["평타로 화상(화염 흔적) 누적 → 능력 적중 시 화상 시간 갱신","화염 대시로 파고들어 추격, 지나간 불길로 지속 피해","적이 뭉치면 충격 폭발로 광역 기절 후 마무리"],"counterItems":["Spirit Shielding","Debuff Reducer"],"confidence":"high","abilities":[{"slot":1,"en":"Napalm","ko":"네이팜","desc":"인화성 혼합물을 뿜어내 마법 피해를 입히고, 둔화 효과를 적용하며, 대상이 네이팜을 뒤집어쓰게 합니다.","brief":"전방 분사, 마법 피해·둔화","short":"분사·둔화","tip":"앞쪽으로 뿜는 기술이니 옆으로 비켜서고, 맞으면 거리를 벌리세요"},{"slot":2,"en":"Flame Dash","ko":"화염 대시","desc":"전방으로 대시해 둔화 저항 효과를 얻고, 이동 경로에 화염 흔적을 남겨 지속 마법 피해를 입힙니다. 활성화 상태에서 [W] 키를 길게 누르면 더 멀리 대시할 수 있습니다.","brief":"전방 대시, 경로에 불길 지속 피해","short":"경로 지속 피해","tip":"대시 뒤에 남는 불길 위에 서 있지 말고 옆으로 피하세요"},{"slot":3,"en":"Afterburn","ko":"화염 흔적","desc":"무기 적중 시 화상 효과가 축적되며 지속 마법 피해를 줍니다. 능력을 사용하면 기본 화상 지속 시간으로 초기화하고, 무기가 적중하면 화상 지속 시간을 연장합니다.","brief":"무기 적중 시 화상 축적·지속 피해","short":"화상 누적","tip":"총에 맞을수록 화상이 길어지니 오래 맞딜하지 마세요"},{"slot":4,"en":"Concussive Combustion","ko":"충격 폭발","desc":"살아 있는 폭탄이 되어, 일정 시간 후에 주변의 모든 적군에게 마법 피해를 입히고 기절시킵니다.충격 폭발은 한 번 시전하면 저지할 수 없습니다.","brief":"지연 후 주변 광역 피해·기절","short":"광역 기절","tip":"시전되면 끊을 수 없으니 보이는 즉시 반경 밖으로 빠지세요"}]},{"id":2,"en":"Seven","ko":"세븐","aliases":["세븐","Seven"],"role":"mystic","complexity":1,"style":"전기 능력으로 전선을 압도하고 궁극기로 한타를 쓸어버리는 마법 딜러","tags":["전선 압박","광역 딜","기절"],"laneStrength":"strong","spikes":"번개 폭탄과 전기 충격으로 초반 라인전이 매우 강합니다. 폭풍 구름을 배우고 마법 아이템이 쌓이면 한타 한 번으로 흐름을 뒤집을 수 있습니다.","strengths":["번개 폭탄으로 전선 정리와 견제를 동시에","전하 충전으로 확실한 기절을 걸 수 있음","폭풍 구름으로 한타 광역 딜이 매우 강함"],"weaknesses":["궁극기 채널링이 끊기면 영향력이 사라짐","기동기가 없어 진입당하면 도망가기 어려움","시야만 가려도 폭풍 구름 피해를 안 받음"],"vsTips":["전하 충전이 걸리면 아군에게서 떨어져 함께 기절하지 마세요","폭풍 구름이 펼쳐지면 벽 뒤로 숨어 시야를 끊으세요","기동기가 없으니 가까이 붙어서 압박하세요"],"withTips":["세븐이 전하 충전을 건 적에게 바로 이어서 공격하세요","세븐이 궁극기를 쓸 때 앞에서 적의 진입을 막아 주세요"],"plan":{"early":"번개 폭탄으로 웨이브를 밀면서 상대 영웅도 같이 맞추세요.","mid":"전선을 빠르게 정리하고 옆 전선에 합류해 킬을 노리세요.","late":"안전한 위치에서 폭풍 구름을 펼쳐 한타를 장악하세요."},"core":["번개 폭탄·전기 충격으로 전선 장악, 뭉친 적은 연쇄 감전","전하 충전으로 기절시키고 폭풍 구름으로 광역 피해","폭풍 구름은 시야 밖 적에겐 안 들어가니 트인 곳에서 사용"],"counterItems":["Silence Wave","Spirit Shielding"],"confidence":"high","abilities":[{"slot":1,"en":"Lightning Ball","ko":"번개 폭탄","desc":"직선으로 날아가는 번개 폭탄을 투척합니다. 반경 내 모든 적군에게 피해를 입힙니다. 폭탄은 적군에게 피해를 입히는 동안 느려지며, 지면이나 구조물에 부딪히면 멈춥니다.","brief":"직선 투척, 범위 내 적 피해","short":"직선 범위 피해","tip":"직선으로 날아오니 옆으로 움직이고, 벽 뒤에 있으면 막힙니다"},{"slot":2,"en":"Static Charge","ko":"전하 충전","desc":"적 영웅에게 충전을 가합니다. 짧은 시간 이후 반경 내에 정전기 충전을 일으켜 적군을 기절시키고 피해를 입힙니다.","brief":"적 영웅 표식, 잠시 후 광역 기절","short":"표식 후 기절","tip":"걸리면 기절 전에 아군과 거리를 벌려 혼자만 맞으세요"},{"slot":3,"en":"Power Surge","ko":"전기 충격","desc":"무기를 충전하여 총탄으로 대상에 전기 충격 피해를 입힙니다. 전기 충격 피해는 대상 근처 적군에게 연쇄 피해를 입힙니다. 연쇄 피해는 충전 사격당 1번씩 발생합니다.","brief":"총탄 전기 피해, 주변 적 연쇄","short":"연쇄 감전","tip":"피해가 주변으로 튀니 아군끼리 붙어 서지 마세요"},{"slot":4,"en":"Storm Cloud","ko":"폭풍 구름","desc":"팽창하는 폭풍우 구름을 자신의 주변으로 내보내 반경 내 모든 적에게 피해를 입힙니다. 적이 시야를 벗어나면 피해를 입지 않습니다.","brief":"주변 확장 구름, 시야 내 적 피해","short":"시야 내 광역 피해","tip":"시야 밖에선 피해가 없으니 엄폐물 뒤로 숨거나 기절로 끊으세요"}]},{"id":3,"en":"Vindicta","ko":"빈딕타","aliases":["빈딕타","Vindicta"],"role":"marksman","complexity":1,"style":"공중에서 저격하며 체력 낮은 적을 마무리하는 원거리 딜러","tags":["저격","마무리","공중"],"laneStrength":"even","spikes":"활공과 까마귀 소환으로 중반부터 견제력이 오르고, 암살이 생기면 먼 거리에서 체력 낮은 적을 끊어냅니다. 무기 아이템이 쌓인 후반에 가장 위협적입니다.","strengths":["활공 중 높은 곳에서 안전하게 공격 가능","암살로 먼 거리에서 마무리 킬을 가져감","강철 말뚝으로 적의 도주를 막음"],"weaknesses":["몸이 약해 붙으면 쉽게 잡힘","공중에 떠 있으면 집중 사격의 표적이 됨","말뚝이 빠지면 위기 탈출 수단이 부족함"],"vsTips":["빈딕타가 날고 있으면 함께 총을 집중해 떨어뜨리세요","체력이 절반 아래면 열린 곳에 서지 말고 엄폐하세요","말뚝을 쓴 직후 거리를 좁혀 근접 교전을 거세요"],"withTips":["빈딕타가 말뚝으로 묶은 적에게 바로 딜을 넣으세요","빈딕타는 몸이 약하니 상대가 붙으면 먼저 막아 주세요"],"plan":{"early":"까마귀와 총으로 견제하며 라스트 히트에 집중하세요.","mid":"높은 곳에서 활공하며 아군 교전에 원거리 딜을 보태세요.","late":"아군 뒤에 머무르며 암살로 체력 낮은 적을 끊으세요."},"core":["활공으로 높이 떠 원거리 사격, 비행 중 총탄에 추가 마법 피해","강철 말뚝으로 묶고 까마귀 소환 출혈로 체력 깎기","체력 절반 이하 적은 암살로 저격, 처치하면 무기 피해 누적"],"counterItems":["Metal Skin","Bullet Resilience"],"confidence":"high","abilities":[{"slot":1,"en":"Stake","ko":"강철 말뚝","desc":"강철 말뚝을 던져 특정 위치에 적군을 결박합니다. 결박된 적군은 밧줄 길이 내로 움직임이 제한됩니다.","brief":"적을 위치에 결박, 이동 제한","short":"제자리 결박","tip":"던지는 동작을 보면 옆으로 피하고, 묶이면 밧줄 범위 안에서 엄폐하세요"},{"slot":2,"en":"Flight","ko":"활공","desc":"공중으로 도약하여 활공합니다. 비행 중에는 무기가 보너스 마법 피해를 입히며, 보유한 아이템의 범위가 증가합니다.","brief":"도약 비행, 무기 추가 마법 피해","short":"비행 사격","tip":"날고 있을 때 총으로 집중 사격하면 쉽게 떨어집니다"},{"slot":3,"en":"Crow Familiar","ko":"까마귀 소환","desc":"소환된 까마귀가 적군에게 충돌 피해를 입히고 총탄 저항을 감소시킵니다. 대상의 현재 체력에 비례하여 피해를 입히는 출혈을 적용합니다.","brief":"충돌 피해·총탄 저항 감소·출혈","short":"출혈·저항 감소","tip":"현재 체력 비례 출혈이라 맞으면 무리한 교전을 피하세요"},{"slot":4,"en":"Assassinate","ko":"암살","desc":"조준경 소총으로 장거리에서 저격하여 큰 피해를 입힙니다. 조준 후 완전히 충전될 때까지 1.0초가 필요하며 충전이 완료되지 않은 상태에서는 적은 피해만 입힙니다. 남은 체력이 50% 미만인 적군에게는 보너스 피해를 입힙니다. 암살로 대상에게 마지막 타격을 가하면 보너스 무기 피해가 부여됩니다.","brief":"장거리 저격, 저체력 적 추가 피해","short":"저체력 저격","tip":"체력이 절반 아래일 때는 저격 각이 열린 곳에 오래 서 있지 마세요"}]},{"id":4,"en":"Lady Geist","ko":"레이디 가이스트","aliases":["레이디 가이스트","Lady Geist"],"role":"mystic","complexity":2,"style":"체력을 소모해 강한 마법 피해를 넣고 흡수로 버티는 마법 딜러","tags":["체력 교환","흡혈","폭딜"],"laneStrength":"strong","spikes":"정수 폭탄과 생명 흡수로 초반 견제와 회복이 모두 좋습니다. 영혼 교환을 배운 뒤에는 체력이 낮은 상황에서도 교전을 뒤집을 수 있습니다.","strengths":["정수 폭탄으로 웨이브와 영웅을 함께 견제","생명 흡수로 피해를 주며 체력을 회복","영혼 교환으로 불리한 교전을 뒤집음"],"weaknesses":["능력이 체력을 소모해 견제에 약해짐","생명 흡수는 시야나 거리를 벗어나면 끊김","회복 감소 효과에 크게 약함"],"vsTips":["생명 흡수가 연결되면 벽 뒤로 가거나 멀리 떨어지세요","정수 폭탄은 터지기까지 지연이 있으니 즉시 자리를 옮기세요","가이스트 체력이 낮을 때 체력 가득한 채로 다가가지 마세요"],"withTips":["가이스트가 생명 흡수 중일 때 상대가 끊지 못하게 막아 주세요","가이스트가 영혼 교환을 쓰면 바로 이어 공격해 마무리하세요"],"plan":{"early":"정수 폭탄으로 견제하고 생명 흡수로 잃은 체력을 채우세요.","mid":"악의로 적을 약화시킨 뒤 아군과 함께 폭딜을 넣으세요.","late":"영혼 교환으로 적 핵심 딜러의 체력을 빼앗아 한타를 뒤집으세요."},"core":["정수 폭탄·악의는 내 체력을 깎아 쓰는 능력, 체력 관리가 핵심","악의 중첩으로 둔화·받는 피해 증가 → 정수 폭탄으로 폭딜","생명 흡수로 체력 회복, 불리할 땐 영혼 교환으로 체력 역전"],"counterItems":["Healbane","Spirit Shielding"],"confidence":"high","abilities":[{"slot":1,"en":"Essence Bomb","ko":"정수 폭탄","desc":"체력의 일부를 희생하여 폭탄을 투척합니다. 폭탄은 짧은 설치 시간이 지난 후 가동되어 적군에게 피해를 입힙니다.자신이 입는 피해 유형은 마법이며 피해를 완화할 수 있습니다.","brief":"체력 희생 투척, 설치 후 피해","short":"체력 소모·설치 피해","tip":"떨어진 뒤 터지기까지 시간이 있으니 낙하 지점에서 바로 벗어나세요"},{"slot":2,"en":"Life Drain","ko":"생명 흡수","desc":"적군과 연결하여 일정 시간 동안 적군의 체력을 흡수하고 자신을 치유합니다. 대상은 반드시 시야 내 그리고 최대 연결 거리 내에 있어야 합니다. 체력을 흡수하는 중에 사격하거나 다른 능력을 사용할 수 있지만, 이동 속도는 감소합니다. : 아군 영웅에게 체력을 부여할 수 있습니다.","brief":"적과 연결해 체력 빼앗아 치유","short":"연결해 체력 뺏기","tip":"시야를 끊거나 사거리 밖으로 나가면 흡수가 끊깁니다"},{"slot":3,"en":"Malice","ko":"악의","desc":"체력을 일부 희생하여 악의를 중첩하는 피의 파편을 발사합니다. 각 중첩은 타격당한 적군에게 둔화 효과를 적용하고 자신이 해당 적군에게 입히는 피해를 증가시킵니다.","brief":"체력 희생 파편, 둔화·피해 증가","short":"둔화·피해 증가","tip":"중첩될수록 받는 피해가 커지니 여러 번 맞았다면 물러나세요"},{"slot":4,"en":"Soul Exchange","ko":"영혼 교환","desc":"대상 적군과 체력을 교환합니다. 교환 후 적군의 최소 체력 비율과 교환으로 획득하는 최소 체력 양은 적군의 현재 체력에 따라 결정됩니다.","brief":"대상 적과 체력 맞바꿈","short":"체력 맞바꿈","tip":"체력을 맞바꾸는 기술이니 가이스트 체력이 낮을 때 근처에 가지 마세요"}]},{"id":6,"en":"Abrams","ko":"에이브럼스","aliases":["에이브럼스","Abrams"],"role":"brawler","complexity":1,"style":"돌진과 흡혈로 버티며 앞에서 싸우는 근접 탱커","tags":["탱커","돌진","흡혈"],"laneStrength":"strong","spikes":"어깨 돌격과 생명 흡수로 초반 근접 교전이 강합니다. 대지 강타를 배우면 먼 거리 진입과 기절 연계가 완성되고, 체력 아이템이 쌓일수록 끈질겨집니다.","strengths":["생명 흡수와 재생으로 오래 버팀","어깨 돌격으로 적을 벽에 밀어 기절시킴","대지 강타로 먼 거리에서 한타 진입 가능"],"weaknesses":["거리를 벌리는 원거리 견제에 약함","회복 감소에 맞으면 버티는 힘이 크게 줄어듦","돌진이 빠지면 적을 쫓아가기 어려움"],"vsTips":["벽을 등지고 서지 말아 어깨 돌격 기절을 피하세요","생명 흡수 범위에 들어오면 바로 거리를 벌리세요","돌격을 쓴 뒤에는 거리를 유지하며 견제하세요"],"withTips":["에이브럼스가 돌격으로 끌고 온 적에게 바로 딜을 넣으세요","에이브럼스가 앞에서 맞아 줄 때 뒤에서 안전하게 공격하세요"],"plan":{"early":"생명 흡수와 근거리 공격으로 상대를 몰아붙이고 돌격으로 킬각을 만드세요.","mid":"대지 강타로 옆 전선에 합류해 교전을 여세요.","late":"앞에서 먼저 진입해 적 딜러를 붙잡고 아군 딜 시간을 버세요."},"core":["어깨 돌격으로 적을 끌고 가 벽에 박으면 기절","생명 흡수·저항의 불꽃으로 맞으면서 회복하는 최전방 탱커","대지 강타로 멀리서 뛰어들어 광역 기절, 한타 개시"],"counterItems":["Healbane","Toxic Bullets"],"confidence":"high","abilities":[{"slot":1,"en":"Siphon Life","ko":"생명 흡수","desc":"근처 적군으로부터 체력을 흡수하여 지속 마법 피해를 주고 입힌 피해의 일부만큼 치유합니다.","brief":"근처 적 체력 흡수·지속 피해","short":"흡혈·지속 피해","tip":"가까이 있을수록 체력을 빼앗기니 근처에서 벗어나세요"},{"slot":2,"en":"Shoulder Charge","ko":"어깨 돌격","desc":"앞으로 돌격해 타격한 영웅에 끌어당기기 효과를 적용합니다. 영웅을 벽에 밀어붙이면 기절 효과를 적용합니다.돌격 중에 영웅과 충돌할 경우 이동 속도가 증가합니다.","brief":"돌진, 벽에 박으면 기절","short":"돌진·벽 기절","tip":"벽을 등지지 말고 돌진 경로에서 옆으로 비켜서세요"},{"slot":3,"en":"Infernal Resilience","ko":"저항의 불꽃","desc":"보너스 방어 속성을 획득합니다. 피해를 입으면 일시적으로 입은 피해량의 일부에 해당하는 재생 효과를 얻습니다.","brief":"피격 시 재생·방어 증가","short":"피격 시 재생","tip":"맞을수록 회복하니 짧게 몰아치거나 회복 감소를 쓰세요"},{"slot":4,"en":"Seismic Impact","ko":"대지 강타","desc":"공중으로 높이 뛰어오른 후 지면을 강타해 마법 피해를 입히고 기절시킵니다.","brief":"도약 후 광역 기절","short":"도약·광역 기절","tip":"공중으로 뛰어오르면 낙하 지점에서 대시로 빠지세요"}]},{"id":7,"en":"Wraith","ko":"레이스","aliases":["레이스","Wraith"],"role":"marksman","complexity":1,"style":"빠른 연사와 카드로 몰아치는 무기 딜러","tags":["무기 딜","순간이동","제압"],"laneStrength":"strong","spikes":"카드 트릭과 고속 연사로 초반 맞딜이 강합니다. 염력이 생기면 한 명을 확실히 묶을 수 있고, 연사 아이템이 쌓이면 근거리 화력이 폭발합니다.","strengths":["고속 연사로 짧은 시간에 큰 무기 피해","투사 이동으로 진입과 도주가 자유로움","염력으로 핵심 적 한 명을 확실히 묶음"],"weaknesses":["몸이 약해 먼저 제압당하면 무력함","무기 피해 위주라 총알 방어에 약함","투사 이동을 쓰면 빠질 수단이 없음"],"vsTips":["고속 연사가 켜지면 엄폐물 뒤로 피하세요","투사 이동을 쓴 직후가 가장 약하니 그때 몰아치세요","총알 방어 아이템을 올려 맞딜을 버티세요"],"withTips":["레이스가 염력으로 띄운 적에게 능력을 모두 쏟으세요","레이스가 연사로 들어갈 때 함께 들어가 화력을 겹치세요"],"plan":{"early":"카드 트릭과 총으로 견제하며 웨이브를 빠르게 밀어 두세요.","mid":"투사 이동으로 옆 전선에 합류해 킬을 노리세요.","late":"염력으로 적 핵심을 묶고 고속 연사로 한타 딜을 쏟으세요."},"core":["총을 맞힐수록 카드 생성 → 카드 트릭으로 무늬별 효과 투척","고속 연사로 순간 화력을 올려 일대일 압도","투사 이동으로 진입·이탈, 염력으로 한 명 띄워 집중 사격"],"counterItems":["Metal Skin","Bullet Resilience"],"confidence":"high","abilities":[{"slot":1,"en":"Card Trick","ko":"카드 트릭","desc":"무기 피해를 입혀 무작위 무늬의 카드를 소환합니다. 카드를 던지면 피해를 입히고 무늬에 따라 각기 다른 효과를 적용합니다. 던져진 카드는 적군이나 조준선이 가리키는 위치로 날아갑니다. 대체 시전으로 첫 번째 카드를 던질 수 있습니다.","brief":"적중 시 쌓아 투척, 무늬별 효과","short":"무늬별 효과 투척","tip":"총에 맞을수록 카드가 쌓이니 오래 맞딜하지 마세요"},{"slot":2,"en":"Project Mind","ko":"투사 이동","desc":"대상 위치로 순간이동합니다.","brief":"지정 위치로 순간이동","short":"순간이동","tip":"순간이동 뒤엔 돌아갈 수단이 없으니 그때 반격하세요"},{"slot":3,"en":"Full Auto","ko":"고속 연사","desc":"일시적으로 연사 속도를 부스트하고, 보너스 마법 피해를 입힙니다.","brief":"연사 속도 증가·추가 마법 피해","short":"추가 마법 피해","tip":"켜진 동안은 정면 맞딜을 피하고 엄폐하세요"},{"slot":4,"en":"Telekinesis","ko":"염력","desc":"적군 영웅을 공중으로 들어올리고, 대상 위치를 향해 내리꽂습니다.","brief":"적 영웅 띄워 지정 위치로 내리꽂음","short":"띄워 내리꽂기","tip":"혼자 있으면 띄워진 뒤 잡히니 아군 곁에 붙어 있으세요"}]},{"id":8,"en":"McGinnis","ko":"맥기니스","aliases":["맥기니스","McGinnis"],"role":"mystic","complexity":1,"style":"포탑과 장벽으로 지역을 장악하는 설치형 마법사","tags":["포탑","지역 장악","회복"],"laneStrength":"strong","spikes":"미니 포탑 덕분에 초반 웨이브 관리와 견제가 쉽습니다. 집중 폭격이 생기면 한타에서 넓은 지역을 압박하고, 지속 시간·쿨다운 아이템으로 포탑 유지력이 오릅니다.","strengths":["포탑으로 자리를 비워도 전선 압박 유지","치유의 영혼으로 아군과 함께 버팀","영혼의 장벽으로 적을 갈라놓고 둔화"],"weaknesses":["포탑 수명이 짧고 부서질 수 있음","기동기가 없어 진입당하면 취약함","집중 폭격 중 느려져 표적이 됨"],"vsTips":["포탑이 깔리면 사거리 밖에서 기다리거나 먼저 부수세요","영혼의 장벽은 근거리 공격으로 깰 수 있으니 갇히면 바로 치세요","집중 폭격 중엔 맥기니스가 느려지니 그때 몰아치세요"],"withTips":["맥기니스 포탑 근처에서 싸우면 딜 우위를 가져갑니다","치유의 영혼 범위 안에서 교전을 이어가세요"],"plan":{"early":"포탑을 깔아 웨이브를 밀고 총과 함께 상대를 견제하세요.","mid":"포탑과 장벽으로 목표물 주변을 장악하며 아군과 함께 움직이세요.","late":"장벽으로 적 진형을 끊고 집중 폭격으로 갇힌 적을 압박하세요."},"core":["미니 포탑을 깔고 그 앞에서 싸우기, 포탑은 내가 쏘는 영웅을 조준","영혼의 장벽으로 적 진형을 갈라 고립, 치유의 영혼으로 유지","집중 폭격은 시전 중 느려지니 안전한 거리에서 광역 폭격"],"counterItems":["Spirit Shielding"],"confidence":"high","abilities":[{"slot":1,"en":"Mini Turret","ko":"미니 포탑","desc":"적군을 공격하여 지속 마법 피해를 입히는 포탑을 배치합니다. 포탑은 제한된 시간이 지나면 사라집니다.포탑은 트루퍼와 주요 목표물에 감소된 피해를 입힙니다.","brief":"적 자동 사격 설치물 배치","short":"자동 사격","tip":"포탑은 오래가지 않으니 사거리 밖에서 버티거나 부수세요"},{"slot":2,"en":"Medicinal Specter","ko":"치유의 영혼","desc":"근처 아군을 치유하는 물약을 배치합니다.","brief":"근처 아군 치유 물약 배치","short":"아군 치유","tip":"회복 범위 밖으로 적을 끌어내서 싸우세요"},{"slot":3,"en":"Spectral Wall","ko":"영혼의 장벽","desc":"지나는 적에게 둔화를 적용하는 장벽을 시전합니다. 장벽을 폭발시켜 지형을 반으로 가르고 근처 적군에게 피해를 입힐 수 있습니다. 시전 후, 키 또는 능력 3 키를 눌러 원하는 시점에 장벽을 폭발시킬 수 있습니다. 근거리 공격으로 장벽을 파괴할 수 있습니다.","brief":"통과 적 둔화 벽, 폭발 시 피해","short":"둔화 벽","tip":"장벽은 근거리 공격으로 부술 수 있으니 갇히면 바로 깨세요"},{"slot":4,"en":"Heavy Barrage","ko":"집중 폭격","desc":"대상 위치에 유도 로켓을 연속으로 발사합니다.맥기니스에게 둔화 효과가 적용되지만, 활력을 계속 사용할 수 있습니다.","brief":"지정 위치에 유도 로켓 연사","short":"유도 로켓 연사","tip":"폭격 지점에서 계속 움직여 벗어나고, 느려진 맥기니스를 노리세요"}]},{"id":10,"en":"Paradox","ko":"패러독스","aliases":["패러독스","Paradox"],"role":"marksman","complexity":3,"style":"시간 정지와 위치 교환으로 적을 끌어오는 컨트롤 딜러","tags":["군중 제어","위치 교환","폭딜"],"laneStrength":"even","spikes":"파동 수류탄과 키네틱 카빈으로 초반 견제가 가능합니다. 역설 전환이 생기면 적 한 명을 아군 쪽으로 끌어와 확실한 킬각을 만들 수 있습니다.","strengths":["키네틱 카빈으로 먼 거리에서 시간 정지","역설 전환으로 적을 아군 쪽에 끌어옴","시간 장벽으로 적 투사체와 총알을 막음"],"weaknesses":["능력 적중에 크게 의존해 다루기 어려움","역설 전환 후 자신이 적 쪽에 남음","능력이 빠지면 맞딜이 약함"],"vsTips":["키네틱 카빈 충전이 보이면 엄폐물 뒤로 숨으세요","역설 전환 투사체를 좌우로 움직여 피하세요","위치를 바꾼 뒤 적진에 남은 패러독스를 바로 노리세요"],"withTips":["패러독스가 끌어온 적을 즉시 집중 공격하세요","시간 장벽을 통과해 쏘면 강해지니 장벽 뒤에서 싸우세요"],"plan":{"early":"파동 수류탄과 카빈으로 견제하며 안전하게 파밍하세요.","mid":"역설 전환과 수류탄 연계로 옆 전선에서 킬을 만드세요.","late":"적 핵심 딜러를 아군 쪽으로 끌어오고 시간 장벽으로 아군 화력을 높이세요."},"core":["파동 수류탄으로 둔화·받는 피해 중첩 → 키네틱 카빈 저격","시간 장벽으로 적 탄환을 멈추고 아군 총탄 강화","역설 전환으로 적을 아군·장벽 쪽으로 끌어와 처치"],"counterItems":["Debuff Reducer"],"confidence":"high","abilities":[{"slot":1,"en":"Pulse Grenade","ko":"파동 수류탄","desc":"지면에 떨어지면 파동을 일으키기 시작하는 수류탄을 투척합니다. 파동이 발생할 때마다 범위가 확장되며, 마법 피해를 입히고, 시간 둔화 및 중첩되는 피해 증가를 적용해 패러독스가 해당 대상에게 주는 피해가 증가합니다.","brief":"확장 파동, 피해·시간 둔화","short":"시간 둔화","tip":"펄스마다 범위가 넓어지니 떨어지자마자 바로 벗어나세요"},{"slot":2,"en":"Time Wall","ko":"시간 장벽","desc":"시간을 왜곡하는 벽을 만들어 벽에 닿는 모든 적군 투사체 및 총탄의 시간을 정지하고, 아군 총탄의 속도와 피해를 증가시킵니다.벽에 닿은 적군은 잠시 동안 둔화됩니다.","brief":"적 총탄 정지·아군 총탄 강화 벽","short":"총탄 정지 벽","tip":"장벽에 닿은 총알은 멈추니 장벽을 돌아서 공격하세요"},{"slot":3,"en":"Kinetic Carbine","ko":"키네틱 카빈","desc":"강력한 시간 에너지를 충전하여 발사합니다. 적중한 적에게 마법 피해를 입히고 시간 정지를 적용합니다. 무기 피해에 따라 입히는 피해가 증가합니다. 충전 중에는 이동 속도가 증가합니다. 공중에서 충전 중일 때, 키를 눌러 천천히 움직일 수 있습니다.","brief":"충전 사격, 마법 피해·시간 정지","short":"충전·시간 정지","tip":"충전 중 이동이 빨라지니 충전이 보이면 바로 엄폐하세요"},{"slot":4,"en":"Paradoxical Swap","ko":"역설 전환","desc":"자신과 대상 적군 영웅의 위치를 바꾸는 투사체를 발사합니다.","brief":"투사체 적중 적과 위치 교체","short":"위치 교체","tip":"투사체를 피하면 끌려가지 않으니 계속 좌우로 움직이세요"}]},{"id":11,"en":"Dynamo","ko":"다이나모","aliases":["다이나모","Dynamo"],"role":"mystic","complexity":2,"style":"광역 기절과 회복으로 한타를 여는 서포터형 마법사","tags":["서포터","광역 기절","회복"],"laneStrength":"weak","spikes":"라인전 압박은 약하지만 특이점을 배우는 시점부터 한타 영향력이 크게 오릅니다. 쿨다운·생명 아이템을 갖추면 궁극기를 더 자주 노릴 수 있습니다.","strengths":["특이점으로 여러 적을 끌어모아 기절","양자 결속으로 아군과 함께 순간이동","소생의 오로라로 주변 아군을 회복"],"weaknesses":["직접 딜이 약해 라인전 압박이 적음","특이점이 끊기면 영향력이 크게 줄어듦","오로라 채널링 중에는 공격력이 약함"],"vsTips":["다이나모가 다가오면 뭉치지 말고 흩어지세요","오로라 회복은 회복 감소나 폭딜로 이겨내세요","라인전에서 적극적으로 견제해 성장을 늦추세요"],"withTips":["다이나모가 특이점으로 모은 적에게 광역 능력을 쓰세요","소생의 오로라 범위 안으로 들어가 회복을 받으세요"],"plan":{"early":"충격파로 견제하며 전선 파트너가 편하게 파밍하도록 도우세요.","mid":"양자 결속으로 옆 전선 갱킹에 합류하세요.","late":"측면이나 위쪽에서 양자 결속으로 진입해 특이점으로 한타를 여세요."},"core":["양자 결속 순간이동으로 진입 → 특이점으로 광역 흡입·기절","특이점에 맞춰 아군 광역기를 연계하는 게 한타 승부처","소생의 오로라로 아군 유지, 충격파로 띄워 전선 견제"],"counterItems":["Healbane"],"confidence":"high","abilities":[{"slot":1,"en":"Kinetic Pulse","ko":"충격파","desc":"지면을 따라 에너지 파동을 방출해 마법 피해를 입히고 들어올리기 효과를 적용합니다.","brief":"지면 파동, 마법 피해·들어올리기","short":"띄우기 파동","tip":"땅을 타고 오는 파동이니 경로에서 옆으로 비켜서세요"},{"slot":2,"en":"Quantum Entanglement","ko":"양자 결속","desc":"잠시 동안 대상 지정 불가 상태가 되어 대상 위치로 순간 이동합니다. 사용 시 활력을 회복합니다. : 근처 아군과 함께 이동합니다.","brief":"지정 불가 상태로 순간이동","short":"순간이동","tip":"순간이동 직후 진입이 이어지니 궁극기를 경계하세요"},{"slot":3,"en":"Rejuvenating Aurora","ko":"소생의 오로라","desc":"능력 집중 시간 동안 자신과 근처 아군을 지속적으로 치유합니다.대시하거나 근거리 공격을 해도 능력 집중이 중단되지 않습니다.","brief":"집중 중 자신·근처 아군 지속 치유","short":"아군 치유","tip":"회복 중인 적에겐 회복 감소 효과로 회복량을 줄이세요"},{"slot":4,"en":"Singularity","ko":"특이점","desc":"손 안에 특이점을 생성해 지속 마법 피해를 입히고 기절 효과를 부여하며, 주변의 적을 끌어들입니다.","brief":"주변 적 끌어당겨 기절·지속 피해","short":"끌어당겨 기절","tip":"주변 적을 끌어당기니 다이나모 근처에 뭉쳐 있지 마세요"}]},{"id":12,"en":"Kelvin","ko":"켈빈","aliases":["켈빈","Kelvin"],"role":"brawler","complexity":2,"style":"얼음길로 아군을 이끌고 둔화와 보호로 버티게 하는 지원형 전사","tags":["둔화","회복","기동"],"laneStrength":"even","spikes":"냉각 수류탄으로 초반부터 견제와 회복을 함께 챙깁니다. 얼음 쉼터가 생기면 한타와 목표물 수비가 크게 강해집니다.","strengths":["냉각 수류탄으로 딜과 아군 회복을 동시에","얼음길로 아군과 함께 빠르게 이동","얼음 쉼터로 아군과 목표물을 보호"],"weaknesses":["극지 광선 중 이동이 느려 노려지기 쉬움","순간 폭딜이 부족함","얼음길은 적도 함께 이용할 수 있음"],"vsTips":["극지 광선은 오래 맞을수록 느려지니 엄폐물로 끊으세요","냉각 수류탄 구름에서 바로 빠져나오세요","얼음 쉼터가 생기면 무리하지 말고 끝날 때까지 기다리세요"],"withTips":["켈빈의 얼음길을 타고 함께 진입하거나 빠지세요","위험할 때 얼음 쉼터 안으로 들어가 회복하세요"],"plan":{"early":"냉각 수류탄으로 견제와 회복을 챙기며 전선을 유지하세요.","mid":"얼음길로 아군을 데리고 다른 전선에 빠르게 합류하세요.","late":"얼음 쉼터로 무너지는 아군이나 목표물을 지키며 한타를 버티세요."},"core":["얼음길로 아군과 함께 빠르게 진입·후퇴","극지 광선은 오래 맞힐수록 이속·연사 둔화가 커짐","냉각 수류탄으로 아군 치유, 위기의 아군은 얼음 쉼터로 보호"],"counterItems":["Healbane"],"confidence":"high","abilities":[{"slot":1,"en":"Frost Grenade","ko":"냉각 수류탄","desc":"폭발 시 적군을 얼어붙게 만드는 구름을 드리우는 수류탄을 투척합니다. 구름은 아군을 치유하고, 적군에는 마법 피해를 입히며 이동 속도 감소를 적용합니다.","brief":"적 피해·둔화, 아군 치유 구름","short":"둔화·아군 치유","tip":"구름 안에 있으면 피해와 둔화가 이어지니 바로 벗어나세요"},{"slot":2,"en":"Ice Path","ko":"얼음길","desc":"켈빈이 공중에 떠 있는 얼음길을 만들고 자신과 아군에게 이동 속도 보너스를 부여하는 눈을 뿌립니다. 능력 지속 시간 동안 켈빈의 둔화 저항이 60% 증가합니다. 적군도 얼음길 위를 걸을 수 있습니다. 대시 / 웅크리기/활주 키를 누르면 얼음길에서 위아래로 이동할 수 있습니다.","brief":"공중 길 생성·아군 이동 속도 증가","short":"공중 길·가속","tip":"얼음길은 적도 탈 수 있으니 추격이나 도주에 이용하세요"},{"slot":3,"en":"Arctic Beam","ko":"극지 광선","desc":"전방에 얼어붙을 정도로 차가운 에너지를 발사하여 대상에 피해를 입히고 이동 속도와 연사 속도를 점차적으로 둔화시킵니다. 대상이 광선을 오래 맞을수록 둔화 효과가 증가합니다. 극지 광선을 발사하는 동안에는 자신의 이동 속도가 감소합니다. 광선으로도 영혼을 획득할 수 있습니다.","brief":"전방 냉기 발사, 점점 강한 둔화","short":"점점 강한 둔화","tip":"맞을수록 둔화와 공속 감소가 커지니 시야를 끊으세요"},{"slot":4,"en":"Frozen Shelter","ko":"얼음 쉼터","desc":"자신이나 영웅 하나를 대상으로 주변 공기를 얼려, 대상 주위에 방탄 돔을 생성합니다. 돔 안에 있는 아군은 급속 재생을 얻으며, 적군은 둔화됩니다.주요 목표물이 얼음 쉼터 내에 있는 경우 무적 상태가 되며 얼어붙습니다.","brief":"방탄 돔, 아군 재생·적 둔화","short":"방탄 돔","tip":"돔 안의 적은 빠르게 회복하니 끝날 때까지 거리를 두세요"}]},{"id":13,"en":"Haze","ko":"헤이즈","aliases":["헤이즈","Haze"],"role":"assassin","complexity":1,"style":"은신과 탄무로 적을 쓸어버리는 후반형 무기 암살자","tags":["후반형","은신","무기 딜"],"laneStrength":"weak","spikes":"라인전은 약한 편입니다. 무기 아이템이 쌓이는 중후반부터 표적 고정과 탄무로 화력이 폭발합니다.","strengths":["표적 고정으로 오래 쏠수록 피해가 커짐","연막탄으로 접근과 도주가 쉬움","탄무로 주변 적을 한꺼번에 정리"],"weaknesses":["초반 라인전과 성장 전에 약함","탄무 중 기절에 끊기기 쉬움","가까이 있으면 은신이 보임"],"vsTips":["초반에 적극적으로 견제해 성장을 늦추세요","탄무가 시작되면 기절이나 침묵으로 바로 끊으세요","은신은 가까이서 보이니 주변을 잘 살피세요"],"withTips":["헤이즈가 재운 적은 함께 몰아쳐 한 번에 잡으세요","초반엔 대신 전선을 버텨 헤이즈가 성장할 시간을 벌어 주세요"],"plan":{"early":"안전하게 라스트 히트를 챙기며 무리한 교전은 피하세요.","mid":"정글과 웨이브를 돌며 무기 아이템을 빠르게 갖추세요.","late":"연막탄으로 적 뒤로 돌아가 탄무로 한타를 정리하세요."},"core":["표적 고정: 한 대상을 계속 쏠수록 총탄 피해 증가","연막탄 은신으로 접근, 수면 단검으로 재워 일대일 각 만들기","적이 모인 곳에서 탄무로 근처 적 전원 자동 조준 사격"],"counterItems":["Metal Skin","Return Fire"],"confidence":"high","abilities":[{"slot":1,"en":"Sleep Dagger","ko":"수면 단검","desc":"피해를 입히고 수면에 빠뜨리는 단검을 대상을 향해 투척합니다. 수면에 빠진 대상은 피해를 입으면 깨어납니다. 단검을 투척해도 투명 상태가 해제되지 않습니다. 수면 단검은 적군의 능력 집중을 방해하지 않습니다.","brief":"적 피해·수면, 피격 시 깨어남","short":"피격 시 깨는 수면","tip":"피해를 받으면 금방 깨니 잠든 아군을 공격해 깨워 주세요"},{"slot":2,"en":"Smoke Bomb","ko":"연막탄","desc":"투명 상태로 전환되면서 시야에서 점점 사라지고 질주 속도를 얻습니다. 투명 상태는 공격 시 해제되지만, 아이템 사용 시에는 해제되지 않습니다. 반경 내에 있는 적군은 투명화된 형체를 볼 수 있습니다.","brief":"투명화·질주 속도 증가","short":"투명·가속","tip":"가까이 있으면 은신이 보이니 수상한 곳을 경계하세요"},{"slot":3,"en":"Fixation","ko":"표적 고정","desc":"사격 시 대상에게 입히는 총탄 피해가 점차 증가합니다. 총탄 타격당 중첩 1회를 얻으며 헤드샷인 경우 3회를 얻습니다.","brief":"계속 사격 시 총탄 피해 점증","short":"피해 점증","tip":"오래 맞을수록 피해가 커지니 엄폐로 사격을 끊으세요"},{"slot":4,"en":"Bullet Dance","ko":"탄무","desc":"능력을 시전하면 근처 적군에게 완벽한 명중률로 무기를 발사하고 추가로 총탄 피해를 입힙니다.","brief":"근처 적 필중 난사·추가 총탄 피해","short":"필중 난사","tip":"기절이나 침묵으로 끊고, 총알 방어를 올려 버티세요"}]},{"id":14,"en":"Holliday","ko":"홀리데이","aliases":["홀리데이","Holliday"],"role":"marksman","complexity":3,"style":"헤드샷과 화약통으로 견제하는 정밀 사격 딜러","tags":["헤드샷","폭발물","제압"],"laneStrength":"strong","spikes":"명사수 덕분에 헤드샷만 잘 맞혀도 초반부터 강합니다. 마법 밧줄이 생기면 바운스 패드와 연계한 기습으로 한 명을 확실히 잡습니다.","strengths":["명사수 헤드샷으로 거리 상관없이 견제","바운스 패드로 기습과 탈출이 자유로움","마법 밧줄로 적을 끌어와 기절시킴"],"weaknesses":["헤드샷 실력에 따라 위력 차이가 큼","화약통은 터지기 전 피할 시간이 있음","근접 난전에서는 버티기 어려움"],"vsTips":["가만히 서 있지 말고 계속 움직여 헤드샷을 피하세요","화약통이 떨어지면 터지기 전에 바로 벗어나세요","바운스 패드가 깔린 곳은 기습 경로이니 경계하세요"],"withTips":["홀리데이의 바운스 패드를 같이 타고 기습에 참여하세요","밧줄로 끌려온 적을 바로 집중 공격하세요"],"plan":{"early":"헤드샷으로 상대 체력을 깎고 화약통으로 웨이브를 정리하세요.","mid":"바운스 패드로 높은 곳을 잡아 견제하며 옆 전선 기습을 노리세요.","late":"멀리서 헤드샷으로 딜을 넣고 밧줄로 적 딜러를 끌어오세요."},"core":["명사수: 쿨마다 헤드샷 추가 피해, 항상 머리 조준","화약통을 쏴서 원하는 타이밍에 폭발, 띄운 적을 헤드샷","바운스 패드로 기동·진입, 마법 밧줄로 끌고 와 기절"],"counterItems":["Bullet Resilience"],"confidence":"high","abilities":[{"slot":1,"en":"Powder Keg","ko":"화약통","desc":"지연 시간 후 폭발하는 화약통을 던져 마법 피해를 입히고, 적군에게 불을 붙이고 들어올리기 효과를 적용합니다.사격, 근거리 공격, 또는 다른 화약통의 폭발을 통해 원하는 시점에 화약통을 폭발시킬 수 있습니다.화상 효과는 중첩되므로, 여러 화약통이 겹치면 화상 피해가 합산됩니다.대체 시전으로 홀리데이 앞에 화약통을 배치할 수 있습니다.","brief":"지연 폭발, 화상·들어올리기","short":"화상·띄우기","tip":"터지기까지 지연이 있으니 통이 보이면 즉시 피하세요"},{"slot":2,"en":"Bounce Pad","ko":"바운스 패드","desc":"영웅을 공중으로 날려 올리는 바운스 패드를 지면에 설치합니다.플레이어는 착지 시 폭발을 일으키며 근처 적군에게 피해를 입힙니다.폭발은 하나의 바운스 패드에서 한 명당 한 번만 발생합니다.","brief":"밟으면 공중 도약, 착지 폭발 피해","short":"도약·착지 피해","tip":"패드로 날아와 착지 폭발을 하니 패드 근처에서 거리를 두세요"},{"slot":3,"en":"Crackshot","ko":"명사수","desc":"헤드샷 명중 시 대상에 보너스 피해를 입히고 점진적 이동 속도 둔화 페널티를 적용합니다. 이 효과는 쿨다운 상태가 아닐 때만 적용됩니다.비영웅 대상 적중 시 쿨다운이 50% 감소합니다.명사수에는 무기 피해 감소 범위가 적용되지 않으며 주요 목표물은 대상에서 제외됩니다.","brief":"헤드샷 시 추가 피해·이동 둔화","short":"헤드샷 강화","tip":"헤드샷을 맞으면 느려지니 직선으로 움직이지 마세요"},{"slot":4,"en":"Spirit Lasso","ko":"마법 밧줄","desc":"밧줄을 던져 마법 피해를 입히고, 끌어당기기 효과와 기절 효과를 적용합니다.바운스 패드를 사용하면 마법 밧줄의 지속 시간이 증가합니다.","brief":"적 끌어당기고 기절·마법 피해","short":"끌어당겨 기절","tip":"끌려가 기절하니 홀리데이와 거리를 두고 엄폐물을 끼세요"}]},{"id":15,"en":"Bebop","ko":"비밥","aliases":["비밥","Bebop"],"role":"brawler","complexity":2,"style":"갈고리로 적을 끌어와 어퍼컷과 폭탄으로 터뜨리는 근접 제압형","tags":["갈고리","제압","폭딜"],"laneStrength":"strong","spikes":"갈고리팔과 폭발 어퍼컷 연계가 초반부터 위협적입니다. 점착 폭탄은 맞힐 때마다 강해져 중후반으로 갈수록 폭딜이 커집니다.","strengths":["갈고리팔로 적을 끌어와 확실한 연계","점착 폭탄이 맞힐수록 영구 강화됨","하이퍼 빔으로 넓은 범위에 지속 딜"],"weaknesses":["갈고리가 빗나가면 진입 수단이 부족함","하이퍼 빔 채널링이 끊기면 딜이 사라짐","점착 폭탄을 못 맞히면 성장이 더딤"],"vsTips":["미니언 뒤에 서서 갈고리팔을 막으세요","점착 폭탄이 붙으면 터지기 전에 아군과 떨어지세요","하이퍼 빔은 옆으로 벗어나거나 엄폐물 뒤로 피하세요"],"withTips":["비밥이 끌어온 적에게 바로 능력을 쏟아부으세요","위험할 땐 비밥 갈고리로 구출받을 수 있으니 시야 안에 있으세요"],"plan":{"early":"미니언 사이로 갈고리 각을 노려 어퍼컷 연계로 상대를 압박하세요.","mid":"점착 폭탄을 꾸준히 맞혀 키우면서 옆 전선 갱킹을 다니세요.","late":"갈고리로 적 핵심을 끌어오고 하이퍼 빔으로 한타 딜을 넣으세요."},"core":["갈고리팔로 한 명을 끌어와 폭발 어퍼컷·점착 폭탄 연계","점착 폭탄은 영웅 적중·처치할수록 피해가 영구 증가","갈고리팔은 아군 구출에도 사용, 한타엔 하이퍼 빔 광역딜"],"counterItems":["Spirit Shielding"],"confidence":"high","abilities":[{"slot":1,"en":"Exploding Uppercut","ko":"폭발 어퍼컷","desc":"근처 적군에게 근거리 공격 피해를 입히고 밀쳐내기 효과를 적용합니다. 착지한 적군은 근처 다른 적군에게 마법 피해를 입히고 감소된 연사 속도 효과를 적용합니다. 폭발 어퍼컷은 아군에게도 사용할 수 있습니다.","brief":"근처 적 타격·밀쳐내기, 착지 피해","short":"밀쳐내기·착지 피해","tip":"근접 범위 기술이니 비밥에게 너무 붙지 마세요"},{"slot":2,"en":"Sticky Bomb","ko":"점착 폭탄","desc":"근처 대상에게 폭탄을 던집니다. 폭탄은 일정 지연 시간 후 폭발하여 근처 적군에게 마법 피해를 입힙니다. 폭탄이 적군 영웅에 명중하거나 적군 영웅을 처치할 경우, 점착 폭탄이 영구적인 보너스 피해를 얻습니다.이 중첩은 60회 명중 및 7회 처치 후 절반으로 감소합니다.","brief":"근처 대상 부착, 지연 후 폭발","short":"부착 후 폭발","tip":"폭탄이 붙으면 터지기 전에 아군과 거리를 벌리세요"},{"slot":3,"en":"Grapple Arm","ko":"갈고리팔","desc":"기계손을 발사해, 처음 적중한 대상에게 끌어당기기 효과를 적용합니다. 갈고리팔은 아군에게도 사용할 수 있습니다.","brief":"첫 적중 대상 끌어당김","short":"끌어당김","tip":"처음 맞은 대상만 끌려가니 미니언 뒤에 서세요"},{"slot":4,"en":"Hyper Beam","ko":"하이퍼 빔","desc":"강력한 에너지 돌풍을 시전해 마법 피해를 입히고 둔화를 적용합니다.","brief":"전방 에너지 방사, 마법 피해·둔화","short":"광선·둔화","tip":"빔 방향에서 옆으로 빠지고 엄폐물을 이용하세요"}]},{"id":16,"en":"Calico","ko":"칼리코","aliases":["칼리코","Calico"],"role":"assassin","complexity":2,"style":"그림자로 숨어들어 근접 기습하는 암살자","tags":["기습","근접","은밀 이동"],"laneStrength":"even","spikes":"암흑의 폭탄으로 전선 견제가 가능하고, 암흑의 그림자를 배우면 진입 후 생존력이 생겨 기습이 훨씬 강해집니다.","strengths":["에이바로 미니맵에서 사라져 기습 가능","도약 타격으로 빠르게 붙고 소량 회복","암흑의 그림자로 위기 때 대상 지정 불가"],"weaknesses":["근접 위주라 원거리 견제에 약함","에이바 상태에서 맞으면 이동 속도 초기화","진입 후 빠질 수단이 제한적임"],"vsTips":["칼리코가 미니맵에서 사라지면 기습을 대비해 아군 곁에 있으세요","에이바 상태로 다가오면 바로 맞혀 속도를 끊으세요","근접 거리를 주지 말고 물러나며 견제하세요"],"withTips":["칼리코가 기습할 때 같이 들어가 딜을 보태세요","칼리코는 근접형이니 상대 원거리 견제를 대신 받아 주세요"],"plan":{"early":"암흑의 폭탄으로 견제하고 도약 타격으로 딜 교환과 회복을 챙기세요.","mid":"에이바로 맵을 돌며 혼자 있는 적을 기습하세요.","late":"측면에서 기습해 적 딜러를 잡고 암흑의 그림자로 빠져나오세요."},"core":["에이바로 변신해 미니맵에서 숨고 빠르게 접근","도약 타격·암흑의 폭탄으로 기습 후 근접 마무리","위험하면 암흑의 그림자로 대상 지정 불가 상태로 이탈"],"counterItems":[],"confidence":"low","abilities":[{"slot":1,"en":"Gloom Bombs","ko":"암흑의 폭탄","desc":"일정 지연 시간 후 폭발하여 마법 피해를 입히는 폭탄을 여러 개 투척합니다.적군이 여러 폭탄에 맞을 경우 1개를 제외한 나머지 폭탄에 대한 피해는 65%로 감소합니다.","brief":"여러 개 투척, 지연 후 마법 피해","short":"다발 지연 피해","tip":"지연 후 터지니 폭탄이 떨어진 곳에서 바로 벗어나세요"},{"slot":2,"en":"Leaping Slash","ko":"도약 타격","desc":"전방으로 대시한 후 원형 범위 내에 있는 모든 적군을 타격해 근거리 공격 피해를 입힙니다.능력으로 최소 한 명의 영웅을 타격하면 소량의 체력을 치유합니다.","brief":"대시 후 주변 베기, 적중 시 치유","short":"대시 베기·치유","tip":"돌진 후 주변을 베니 거리를 두고 옆으로 피하세요"},{"slot":3,"en":"Ava","ko":"에이바","desc":"암흑의 힘을 빌려 에이바의 영혼과 하나가 됩니다. 시간이 지남에 따라 추가 이동 속도를 얻고, 미니맵에서 숨겨집니다.적군 영웅에게 피해를 입으면 보너스 이동 속도가 초기화되며 잠시 동안 에이바의 영혼과 하나가 될 수 없습니다.","brief":"이동 속도 점증·미니맵에서 숨김","short":"가속·미니맵 숨김","tip":"피해를 주면 이동 속도가 초기화되니 보이는 즉시 맞히세요"},{"slot":4,"en":"Return to Shadows","ko":"암흑의 그림자","desc":"즉시 암흑의 그림자로 변신하여 대상 지정 불가 상태가 되며, 추가 이동 속도를 얻고 마법 피해를 입힙니다.일정 지연 시간 후 그림자 상태에서 해제되며 다시 마법 피해를 입힙니다.","brief":"지정 불가·이속 증가, 전후 피해","short":"지정 불가","tip":"그림자에서 나올 때 다시 피해를 주니 그 자리에서 떨어지세요"}]},{"id":17,"en":"Grey Talon","ko":"그레이 탈론","aliases":["그레이 탈론","Grey Talon"],"role":"marksman","complexity":2,"style":"먼 거리에서 화살로 견제하고 부엉이로 마무리하는 원거리 딜러","tags":["장거리","견제","마무리"],"laneStrength":"strong","spikes":"위력의 화살로 초반부터 장거리 견제가 강합니다. 부엉이 비행이 생기면 멀리 있는 적에게도 기절과 마무리를 노릴 수 있습니다.","strengths":["위력의 화살로 먼 거리에서 강하게 견제","영혼 트랩으로 진입하는 적을 무력화","부엉이 비행으로 먼 적까지 기절시킴"],"weaknesses":["가까이 붙으면 대처 수단이 적음","화살 세례 중 공중에 떠 있어 표적이 됨","부엉이를 조종하는 동안 본체가 무방비"],"vsTips":["위력의 화살은 관통하니 엄폐물 뒤로 움직이세요","트랩이 깔린 길로 들어가지 말고 돌아서 접근하세요","부엉이를 조종하는 동안 본체를 노리세요"],"withTips":["탈론이 견제할 때 앞에서 적의 진입을 막아 주세요","부엉이로 기절시킨 적을 바로 따라가 마무리하세요"],"plan":{"early":"위력의 화살로 상대를 견제하며 안전하게 파밍하세요.","mid":"높은 곳에서 견제하고 부엉이로 다른 전선 킬을 도우세요.","late":"아군 뒤에서 장거리 딜을 넣고 트랩으로 진입로를 막으세요."},"core":["위력의 화살로 먼 거리 관통 견제, 화살 세례로 공중 다발 사격","영혼 트랩을 깔고 위력의 화살로 쏴 즉시 폭발·침묵","도망치는 적은 부엉이 비행으로 마무리, 처치 시 영구 마력"],"counterItems":["Debuff Reducer"],"confidence":"high","abilities":[{"slot":1,"en":"Charged Shot","ko":"위력의 화살","desc":"적군을 관통하는 위력을 모아 담은 화살을 발사합니다. 능력 1 키 또는 키를 길게 누르면 발사 대기 상태가 유지됩니다.","brief":"충전 사격, 적 관통 피해","short":"충전·관통","tip":"적을 관통하니 미니언 뒤도 안전하지 않습니다, 엄폐물을 끼세요"},{"slot":2,"en":"Rain of Arrows","ko":"화살 세례","desc":"공중으로 높이 날아올라 천천히 활공합니다. 공중에 떠 있는 동안에는 무기 피해가 증가하고 다발 공격이 가능해집니다. 키를 누르면 활공 높이가 낮아집니다. 점프/오르기 키를 누르면 활공이 취소됩니다.","brief":"공중 활공, 무기 피해 증가·다발","short":"공중 다발","tip":"공중에 떠 있을 때 집중 사격하면 쉽게 잡힙니다"},{"slot":3,"en":"Spirit Snare","ko":"영혼 트랩","desc":"자동으로 설치되는 트랩을 투척합니다. 설치 완료 후 적군이 반경 안으로 들어오면 트랩이 가동하며 반경 내 적군에게 저주를 걸어 이동 속도 둔화, 능력 집중 방해, 침묵, 무장 해제 효과를 적용하고 아이템 사용을 차단합니다.위력의 화살로 트랩을 사격하면 원하는 시점에 폭발시킬 수 있으며 반경이 증가합니다.","brief":"자동 설치, 둔화·침묵·무장 해제","short":"침묵·무장 해제 덫","tip":"걸리면 능력과 아이템을 못 쓰니 트랩 근처를 피하세요"},{"slot":4,"en":"Guided Owl","ko":"부엉이 비행","desc":"시전 시간 1.5초 후 조종할 수 있는 영혼 부엉이를 날려 보냅니다. 부엉이는 충돌 시 폭발하며 적군은 피해를 입고 기절합니다. [W] 키를 길게 누르면 부엉이의 비행 속도가 빨라집니다. 점프/오르기 키를 누르면 폭발합니다. 부엉이 비행으로 적군 영웅을 처치할 때마다 영구적으로 마력을 얻습니다.","brief":"조종 비행체, 충돌 폭발·기절","short":"조종·충돌 기절","tip":"시전 후 날아오니 엄폐물 뒤로 숨고, 조종 중인 본체를 노리세요"}]},{"id":18,"en":"Mo & Krill","ko":"모와 크릴","aliases":["모와 크릴","Mo & Krill","모 & 크릴","모앤크릴"],"role":"brawler","complexity":3,"style":"땅굴로 파고들어 한 명을 붙잡는 근접 탱커","tags":["탱커","기습","단일 제압"],"laneStrength":"even","spikes":"도발 덕분에 초반 근접 교전 유지력이 좋습니다. 콤보가 생기면 적 한 명을 확실히 묶어 킬을 만들고, 콤보로 잡을 때마다 최대 체력이 늘어납니다.","strengths":["굴파기로 빠르게 접근하고 기습","콤보로 적 한 명을 확실히 묶음","도발 회복으로 근접전에서 오래 버팀"],"weaknesses":["원거리 견제에 맞서기 어려움","콤보 중에는 자신도 움직이지 못함","굴파기 중 맞으면 이동 속도가 줄어듦"],"vsTips":["모와 크릴이 안 보이면 굴파기 기습을 대비하세요","콤보에 걸린 아군은 모와 크릴을 기절시켜 구하세요","모래 폭풍에 맞아 총을 못 쏠 땐 뒤로 빠지세요"],"withTips":["콤보로 묶은 적에게 함께 딜을 넣으세요","굴파기 기습에 맞춰 같이 진입하세요"],"plan":{"early":"도발로 체력을 유지하며 근접 압박을 넣으세요.","mid":"굴파기로 옆 전선에 돌아가 기습하고 콤보로 킬을 만드세요.","late":"굴파기로 적 후방에 파고들어 핵심 딜러를 콤보로 묶으세요."},"core":["굴파기로 땅속 이동해 접근, 솟아오르며 띄우기","모래 폭풍으로 무장 해제 → 콤보로 한 명 묶어 처치","도발로 주변 적을 때리며 회복, 콤보 처치 시 최대 체력 영구 증가"],"counterItems":["Healbane"],"confidence":"high","abilities":[{"slot":1,"en":"Scorn","ko":"도발","desc":"근처 적군에게 피해를 입히고 입힌 피해의 일정 비율로 자신을 치유합니다. 피해 기반 치유 승수는 적군 영웅을 공격했을 때 더 큽니다.","brief":"근처 적 피해·피해 비례 치유","short":"적 피해·자가 치유","tip":"주변 피해로 회복하니 근처에 오래 붙어 있지 마세요"},{"slot":2,"en":"Burrow","ko":"굴파기","desc":"지하로 파고들어 질주합니다. 이동 속도가 증가하고 마법 및 총탄 저항을 얻습니다. 적군 영웅에게 피해를 입으면 속도 보너스가 감소합니다. 지상으로 솟아오르며 마법 피해를 입히고 둔화 효과와 들어올리기 효과를 적용합니다.","brief":"땅속 질주, 솟을 때 피해·둔화","short":"땅굴 질주","tip":"땅속에서 접근할 때 맞히면 느려지니 계속 쏘세요"},{"slot":3,"en":"Sand Blast","ko":"모래 폭풍","desc":"모래를 흩뿌려 전방에 있는 적군에게 무장 해제를 적용하고 피해를 입힙니다.","brief":"전방 적 무장 해제·피해","short":"무장 해제","tip":"맞으면 총을 못 쏘니 그동안 거리를 벌리세요"},{"slot":4,"en":"Combo","ko":"콤보","desc":"능력 집중 시간 동안 적군 영웅을 제자리에 묶어두고 기절시킨 뒤 피해를 입힙니다. 콤보 시전 중 또는 종료 후 3초 이내에 적군 영웅이 사망하면 영구적으로 일정량의 최대 체력을 얻습니다.","brief":"적 영웅 제자리 고정·기절·피해","short":"붙잡아 기절","tip":"걸린 아군은 혼자 못 빠지니 기절로 모와 크릴을 끊으세요"}]},{"id":19,"en":"Shiv","ko":"쉬브","aliases":["쉬브","Shiv","시브"],"role":"brawler","complexity":3,"style":"출혈과 대시로 파고들어 결정타로 마무리하는 근접 전사","tags":["근접","출혈","마무리"],"laneStrength":"even","spikes":"톱니 칼날과 돌격 대시로 초반 교전이 가능하고, 결정타가 생기면 체력 낮은 적을 확실히 마무리합니다. 유혈 덕분에 진입 후 버티는 힘도 좋습니다.","strengths":["톱니 칼날 출혈로 꾸준히 견제","유혈로 피해를 나눠 받아 오래 버팀","결정타로 체력 낮은 적을 마무리"],"weaknesses":["근접해야 해서 원거리 견제에 약함","회복 감소에 맞으면 유지력이 떨어짐","돌격 대시가 빠지면 도주가 어려움"],"vsTips":["칼날 출혈이 쌓이기 전에 뒤로 빠지세요","체력이 낮을 땐 쉬브 근처에 가지 마세요","유혈로 미뤄 둔 피해가 있으니 짧게 끊지 말고 계속 압박하세요"],"withTips":["쉬브가 대시로 마법 저항을 깎은 적에게 마법 능력을 쓰세요","적 체력이 낮아지면 쉬브가 결정타로 마무리하게 두세요"],"plan":{"early":"톱니 칼날로 출혈을 쌓고 돌격 대시로 짧게 들어갔다 빠지세요.","mid":"옆 전선에 합류해 결정타로 킬을 마무리하세요.","late":"유혈로 버티며 적 진영에 파고들어 체력 낮은 적을 끊으세요."},"core":["톱니 칼날로 출혈 중첩, 돌격 대시로 진입하며 마법 저항 감소","피해를 넣어 분노 게이지를 채우면 피해 증가·능력 강화","유혈로 받는 피해를 미루고, 빈사 적은 결정타로 처형"],"counterItems":["Healbane"],"confidence":"high","abilities":[{"slot":1,"en":"Serrated Knives","ko":"톱니 칼날","desc":"적군에게 출혈을 일으키는 칼날을 던집니다. 적군이 칼날을 맞을 때마다 효과가 중첩되고 출혈 지속 시간이 초기화되어 중첩당 출혈 피해가 증가합니다.","brief":"적중마다 출혈 중첩·피해 증가","short":"출혈 중첩","tip":"맞을수록 출혈이 커지니 연달아 맞지 마세요"},{"slot":2,"en":"Slice and Dice","ko":"돌격 대시","desc":"전방으로 대시하며 경로에 있는 적군에게 피해를 입힙니다. 적중당한 적군은 마법 저항이 감소합니다. 이 약화 효과는 중첩될 수 있습니다.","brief":"전방 대시 피해·마법 저항 감소","short":"마법 저항 감소","tip":"맞으면 마법 저항이 깎이니 뒤따르는 능력을 조심하세요"},{"slot":3,"en":"Bloodletting","ko":"유혈","desc":"공격을 받으면 일부 피해만 즉시 입고 나머지 피해는 지연되어 서서히 입게 됩니다. 시전 시 지연된 피해의 일부를 제거할 수 있습니다.","brief":"받는 피해 일부 지연, 시전 시 감소","short":"피해 지연","tip":"피해를 나중에 받는 기술이니 교전을 길게 끌어 압박하세요"},{"slot":4,"en":"Killing Blow","ko":"결정타","desc":"앞으로 도약해 처음 맞은 적 영웅에게 마법 피해를 줍니다. 대상의 체력이 처형 기준 아래면 즉시 처치하고, 결정타로 처치하면 16초 안에 한 번 더 쓸 수 있습니다. 패시브: 적에게 피해를 주면 분노가 차고, 분노가 가득하면 피해가 늘며 다른 능력에 추가 효과가 붙습니다.","brief":"도약 공격, 저체력 적 즉시 처치","short":"저체력 처형","tip":"체력이 낮으면 쉬브가 뛰어드니 미리 거리를 벌리세요"}]},{"id":20,"en":"Ivy","ko":"아이비","aliases":["아이비","Ivy"],"role":"marksman","complexity":3,"style":"아군과 연결해 함께 강해지는 지원형 딜러","tags":["서포터","아군 연결","둔화"],"laneStrength":"even","spikes":"칡덩굴 연결로 아군과 붙어 싸울 때 강합니다. 공중 투하가 생기면 아군을 데리고 날아가 기습할 수 있습니다.","strengths":["칡덩굴 연결로 아군과 보너스·회복 공유","석화로 주변 적 기절과 자가 회복","공중 투하로 아군과 함께 기습"],"weaknesses":["연결할 아군이 없으면 보너스가 절반","시야가 끊기면 연결이 유지되지 않음","피해를 받으면 공중 투하가 잠시 막힘"],"vsTips":["가시 덤불 범위에 서 있지 말고 바로 빠져나오세요","엄폐물로 아이비와 아군 사이 시야를 끊어 연결을 막으세요","석화로 기절시키니 아이비 바로 옆에 붙지 마세요"],"withTips":["아이비와 시야가 이어지는 거리에서 싸워 연결을 유지하세요","공중 투하로 들려 있을 땐 공격할 수 없으니 착지 후 바로 딜을 넣으세요"],"plan":{"early":"가시 덤불로 견제하며 전선 파트너와 연결을 유지하세요.","mid":"공중 투하로 아군을 태워 옆 전선 기습을 노리세요.","late":"핵심 아군에게 연결해 힘을 보태고 석화로 진입한 적을 끊으세요."},"core":["칡덩굴 연결로 아군과 묶여 버프·치유를 나누며 싸움","포박 가시로 둔화, 석화로 주변 기절·자가 회복","공중 투하로 아군을 들고 날아가 진입하거나 구조"],"counterItems":[],"confidence":"low","abilities":[{"slot":1,"en":"Entangling Thorns","ko":"포박 가시","desc":"반경 내 적군에게 피해를 입히고 이동 속도를 둔화시키는 가시 덤불을 소환합니다.","brief":"범위 적 피해·둔화 덤불","short":"둔화 덤불","tip":"가시 범위 안에선 둔화되니 즉시 밖으로 나가세요"},{"slot":2,"en":"Kudzu Connection","ko":"칡덩굴 연결","desc":"근처 아군과 연결되어 보너스와 치유 복제를 얻고, 사격 중 이동 속도 감소를 무시합니다.연결되어 있지 않을 때는 50%의 보너스를 받습니다.연결을 유지하려면 시야가 확보되어야 합니다.","brief":"아군과 연결, 보너스·치유 공유","short":"아군과 치유 공유","tip":"연결은 시야가 필요하니 아이비와 아군 사이를 엄폐물로 끊으세요"},{"slot":3,"en":"Stone Form","ko":"석화","desc":"파괴되지 않는 돌로 변하여 지면을 강타합니다. 근처 적군을 기절시키고 피해를 입힙니다. 최대 체력의 일정 비율만큼 치유됩니다.","brief":"돌로 변해 강타, 주변 기절·치유","short":"강타·주변 기절","tip":"석화 중에는 공격을 아끼고 기절 범위 밖으로 물러나세요"},{"slot":4,"en":"Air Drop","ko":"공중 투하","desc":"아군을 잡아 들고 아군과 함께 비행합니다. 아군을 낙하시키면 마법 피해를 입히는 폭발을 일으킵니다. 비행 종료 시 자신과 아군이 입히는 피해가 증가합니다. 아군에게 사용 시 쿨다운이 30% 감소합니다.피해를 입으면 능력 사용이 잠시 중단됩니다.공중에 떠 있는 동안, 아군은 공격할 수 없으며 -20%의 피해만 입힙니다.","brief":"아군 들고 비행, 낙하 시 폭발","short":"아군 들고 비행","tip":"피해를 받으면 잠시 못 쓰니 아이비를 꾸준히 맞히세요"}]},{"id":25,"en":"Warden","ko":"워든","aliases":["워든","Warden"],"role":"brawler","complexity":2,"style":"속박과 최후의 저항으로 앞에서 버티는 근접 전사","tags":["속박","버티기","근접"],"laneStrength":"strong","spikes":"연금술 플라스크로 초반 맞딜을 유리하게 가져갑니다. 최후의 저항이 생기면 한타 한가운데서 버티며 큰 피해를 줍니다.","strengths":["플라스크로 적 무기 피해와 이동 속도 감소","속박 저주로 적을 묶어 도주 차단","최후의 저항으로 한타 중심에서 버팀"],"weaknesses":["속박 저주는 바로 움직이면 피할 수 있음","최후의 저항은 충전 중 범위를 벗어나면 피함","이동기가 투지 하나뿐이라 견제에 약함"],"vsTips":["속박 저주가 걸리면 즉시 그 자리에서 멀리 이동하세요","최후의 저항 충전이 보이면 범위 밖으로 빠지세요","플라스크에 맞아 총 피해가 줄었을 땐 잠시 물러나세요"],"withTips":["워든이 속박한 적에게 바로 딜을 넣으세요","최후의 저항 중에는 워든 곁에서 함께 싸우세요"],"plan":{"early":"플라스크로 상대 화력을 줄이고 적극적으로 맞딜하세요.","mid":"속박 저주로 적을 묶어 아군과 함께 킬을 만드세요.","late":"앞에서 진입해 최후의 저항으로 버티며 적 진형을 흩트리세요."},"core":["속박 저주: 제자리를 못 벗어난 적은 피해·이동 불가","연금술 플라스크로 적 화력·이속 감소, 투지 방벽 끼고 돌진","적 한가운데서 최후의 저항으로 버티며 흡혈 파동"],"counterItems":["Healbane"],"confidence":"high","abilities":[{"slot":1,"en":"Alchemical Flask","ko":"연금술 플라스크","desc":"피해를 입히는 플라스크를 투척합니다. 타격당한 적군은 무기 피해와 이동 속도가 감소합니다.","brief":"적 피해, 무기 피해·이동 속도 감소","short":"무기 피해·이속 감소","tip":"맞으면 무기 피해와 이동 속도가 줄어드니 그동안 맞딜을 피하세요"},{"slot":2,"en":"Willpower","ko":"투지","desc":"방벽과 보너스 이동 속도를 얻습니다.","brief":"방벽·이동 속도 증가","short":"방벽·가속","tip":"보호막이 생기니 투지를 쓴 직후에는 무리한 맞딜을 피하세요"},{"slot":3,"en":"Binding Word","ko":"속박 저주","desc":"적군 영웅에게 저주를 겁니다. 적군이 탈출 시간 내에 해당 위치에서 벗어나지 못하면 피해를 입고 이동 불가 상태가 됩니다.","brief":"위치 못 벗어나면 피해·이동 불가","short":"못 벗어나면 피해","tip":"저주가 걸리면 바로 처음 위치에서 멀어지세요"},{"slot":4,"en":"Last Stand","ko":"최후의 저항","desc":"2초 충전 후 적군에게 피해를 입히고 입힌 피해의 일정 비율로 자신을 치유하는 파동을 방출합니다.능력 집중 시간 동안 총탄 및 마법 저항이 대폭 증가합니다. 최후의 저항이 활성화된 동안 공포에 면역이 됩니다.","brief":"충전 후 광역 피해·치유·저항 증가","short":"광역·자가 치유","tip":"충전에 시간이 걸리니 그사이 범위 밖으로 빠지세요"}]},{"id":27,"en":"Yamato","ko":"야마토","aliases":["야마토","Yamato"],"role":"assassin","complexity":3,"style":"갈고리로 붙어 칼로 베는 근접 암살자","tags":["근접","돌진","후반형"],"laneStrength":"even","spikes":"핏빛 검술과 비상 검술로 근접 교전이 가능합니다. 그림자 변형이 생기면 상태 이상 면역으로 한타를 뚫고 들어갈 수 있습니다.","strengths":["비상 검술로 적에게 빠르게 붙음","핏빛 검술로 싸우면서 회복","그림자 변형 중 상태 이상 면역"],"weaknesses":["근접해야 해서 원거리 견제에 약함","절대 검술 충전 중에는 노려지기 쉬움","그림자 변형이 끝나면 크게 약해짐"],"vsTips":["비상 검술 갈고리 각을 엄폐물로 막으세요","그림자 변형 중엔 싸우지 말고 끝날 때까지 물러나세요","절대 검술 충전이 보이면 정면에서 비켜서세요"],"withTips":["야마토가 붙은 적에게 둔화나 기절로 도와주세요","그림자 변형 중에 함께 들어가 킬을 이어가세요"],"plan":{"early":"핏빛 검술로 딜 교환을 하며 무리한 진입은 아끼세요.","mid":"비상 검술로 혼자 있는 적을 노려 킬을 쌓으세요.","late":"그림자 변형으로 적 진영에 들어가 킬로 지속 시간을 늘리세요."},"core":["비상 검술 갈고리로 붙고 핏빛 검술로 회복하며 근접전","절대 검술은 모아 베기, 끝까지 모을수록 큰 피해","그림자 변형으로 쿨 초기화·상태이상 면역, 처치하면 연장"],"counterItems":["Healbane"],"confidence":"high","abilities":[{"slot":1,"en":"Power Slash","ko":"절대 검술","desc":"1.4초 동안 능력 집중하여 피해를 증가시키고 완전히 충전된 검으로 타격을 가합니다. 능력 1 또는 키를 누르면 원하는 시점에 타격을 가해 충전된 만큼 피해를 입힐 수 있습니다.","brief":"충전 후 강력한 검 타격","short":"충전 베기","tip":"충전이 보이면 정면에서 벗어나거나 미리 끊으세요"},{"slot":2,"en":"Flying Slash","ko":"비상 검술","desc":"갈고리를 던져 적군에게 걸고, 적군 쪽으로 날아가며, 도달 시 근거리 공격 피해를 입히고 대상에 둔화 효과를 적용합니다.","brief":"갈고리로 적에게 날아가 타격·둔화","short":"갈고리 돌진","tip":"갈고리로 날아와 둔화를 거니 엄폐물로 각을 막으세요"},{"slot":3,"en":"Crimson Slash","ko":"핏빛 검술","desc":"전방에 있는 적군을 검으로 타격해 피해를 입히고 연사 속도를 둔화합니다. 적군 영웅 타격 시 자신을 치유합니다.","brief":"전방 베기, 연사 둔화·자가 치유","short":"베기·치유","tip":"맞으면 공속이 느려지고 야마토는 회복하니 거리를 두세요"},{"slot":4,"en":"Shadow Transformation","ko":"그림자 변형","desc":"야마토의 그림자 영혼이 스며듭니다. 변형 직후 잠시 동안 무적 상태가 됩니다. 무적 상태가 종료된 후 능력 쿨다운이 초기화되고 시전 속도가 60% 빨라집니다. 또한 부정적 상태 효과에 면역이 되고 총탄 및 마법 저항이 크게 증가합니다.영웅 처치 시 자신을 치유하며 그림자 변형의 지속 시간이 연장됩니다.","brief":"무적 후 능력 초기화·상태 면역","short":"무적·초기화","tip":"변형 중엔 제압이 안 통하니 시간을 끌며 물러나세요"}]},{"id":31,"en":"Lash","ko":"래쉬","aliases":["래쉬","Lash"],"role":"assassin","complexity":3,"style":"공중을 누비며 내려찍고 적을 집어던지는 기동형 암살자","tags":["기동","공중","광역 제압"],"laneStrength":"even","spikes":"지면 타격과 채찍질로 초반 교전이 가능합니다. 죽음의 강타가 생기면 여러 적을 들어 던지는 한타 기술이 생깁니다.","strengths":["추격 채찍으로 기동성이 매우 높음","높은 곳에서 내려찍는 지면 타격","죽음의 강타로 여러 적을 기절시킴"],"weaknesses":["진입 후 빠질 수단이 제한적임","죽음의 강타 채널링 중 끊길 수 있음","시야만 끊어도 죽음의 강타를 피함"],"vsTips":["래쉬가 높은 곳에 있으면 내려찍기를 조심하세요","죽음의 강타가 시작되면 벽 뒤로 숨어 시야를 끊으세요","추격 채찍으로 들어온 직후 바로 반격하세요"],"withTips":["래쉬가 죽음의 강타로 던진 적에게 광역 능력을 쓰세요","래쉬가 내려찍을 때 함께 진입하세요"],"plan":{"early":"지면 타격으로 웨이브와 상대를 함께 맞추며 압박하세요.","mid":"추격 채찍으로 맵을 돌며 갱킹하세요.","late":"높은 곳에서 진입해 죽음의 강타로 여러 명을 던지세요."},"core":["추격 채찍으로 공중 이동, 사용하면 공중 점프·대시 초기화","높은 곳에서 지면 타격으로 낙하, 멀리 떨어질수록 강함","죽음의 강타로 여러 명을 들어 내리찍는 한타 진입"],"counterItems":["Spirit Shielding"],"confidence":"high","abilities":[{"slot":1,"en":"Ground Strike","ko":"지면 타격","desc":"지면을 발로 강하게 내리쳐서 전방에 있는 적군에게 피해를 입힙니다. 공중에 떠 있는 상태에서 지면 타격을 시전하면 지면으로 빠르게 강하합니다. 25m를 넘어서면 피해 증가량이 감소합니다.","brief":"전방 적 피해, 공중에서 급강하","short":"급강하","tip":"높이 떨어질수록 강해지니 공중의 래쉬 아래 서 있지 마세요"},{"slot":2,"en":"Grapple","ko":"추격 채찍","desc":"대상에게 채찍을 던지고 대상을 향해 날아서 이동합니다. 추격 채찍을 사용하면 공중 점프와 공중 대시 제한이 초기화됩니다.","brief":"대상에게 날아감·공중 이동 초기화","short":"대상에게 날아감","tip":"채찍으로 날아온 직후를 노려 반격하세요"},{"slot":3,"en":"Flog","ko":"채찍질","desc":"채찍으로 전방에 있는 적군을 공격하고, 입힌 피해의 일부만큼 치유합니다.","brief":"전방 공격, 피해 일부 치유","short":"피해 일부 치유","tip":"맞으면 래쉬가 회복하니 근접 거리를 주지 마세요"},{"slot":4,"en":"Death Slam","ko":"죽음의 강타","desc":"적군을 탐색하여 채찍으로 휘감습니다. 능력 집중 시간이 끝나면 휘감은 적군을 공중으로 잡아 올려 기절시킨 다음 지면으로 내리칩니다. 휘감은 적군과 내리치기 영역 내에 있는 모든 적군은 피해를 입고 둔화됩니다. 키를 누르면 휘감은 적군을 원하는 시점에 내리칠 수 있습니다. 탐색 시간 동안 시야 안에 있지 않거나 시전 범위 밖으로 나간 적군은 채찍으로 휘감을 수 없습니다.","brief":"적 끌어올려 기절, 내리쳐 광역 피해","short":"띄워 광역 피해","tip":"채널링 중 시야나 사거리 밖으로 나가면 잡히지 않습니다"}]},{"id":35,"en":"Viscous","ko":"비스쿠스","aliases":["비스쿠스","Viscous","비스커스"],"role":"mystic","complexity":2,"style":"끈적이로 적을 묶고 큐브로 아군을 지키는 마법사","tags":["군중 제어","보호","광역 딜"],"laneStrength":"strong","spikes":"끈적이 폭탄으로 초반 견제와 전선 정리가 강합니다. 끈적이 공이 생기면 높은 저항으로 한타에 굴러 들어가 기절을 겁니다.","strengths":["끈적이 폭탄으로 견제와 전선 정리","큐브로 아군이나 자신을 위기에서 구함","끈적이 공으로 단단하게 진입해 기절"],"weaknesses":["큐브 안에서는 아무 행동도 못 함","끈적이 펀치는 패리로 막힐 수 있음","공 상태가 아니면 몸이 약한 편"],"vsTips":["끈적이 웅덩이 위에 서 있지 마세요","끈적이 펀치는 패리로 막을 수 있으니 타이밍을 노리세요","큐브에 들어간 적은 나올 때를 기다렸다 공격하세요"],"withTips":["위험할 때 큐브를 받을 수 있도록 비스쿠스 가까이 있으세요","끈적이 공으로 기절시킨 적에게 바로 딜을 넣으세요"],"plan":{"early":"끈적이 폭탄으로 웨이브를 정리하며 상대를 둔화시키고 견제하세요.","mid":"끈적이 펀치로 적을 띄워 아군과 연계 킬을 만드세요.","late":"끈적이 공으로 굴러 들어가 기절을 걸고 큐브로 핵심 아군을 지키세요."},"core":["끈적이 폭탄 늪으로 둔화, 끈적이 펀치로 띄워 연계","큐브로 위기의 아군·자신을 감싸 피해 차단·회복","끈적이 공으로 굴러 들어가 벽에 튕기며 연속 기절"],"counterItems":["Spirit Shielding"],"confidence":"high","abilities":[{"slot":1,"en":"Splatter","ko":"끈적이 폭탄","desc":"끈적이 폭탄을 던져 피해를 입히고 끈적이늪을 생성합니다. 끈적이늪은 반경 내에 있는 적군에게 이동 속도 둔화를 적용합니다.","brief":"투척 피해, 둔화 늪 생성","short":"둔화 늪","tip":"웅덩이에 남아 있으면 계속 느려지니 바로 벗어나세요"},{"slot":2,"en":"The Cube","ko":"큐브","desc":"피해가 차단되며 체력 재생이 증가하는 회복 효과가 있는 끈적이 큐브로 대상을 감쌉니다. 큐브 안에 있는 동안 대상은 새로운 동작을 취할 수 없습니다. 자신에게 시전할 수 있습니다. 점프/오르기 키를 누르면 원하는 시점에 큐브를 해제할 수 있습니다.","brief":"대상 감싸 피해 차단·재생","short":"피해 차단·재생","tip":"큐브 안은 피해를 받지 않으니 공격을 멈추고 나올 때를 노리세요"},{"slot":3,"en":"Puddle Punch","ko":"끈적이 펀치","desc":"지정한 위치에서 솟아오르는 주먹을 만들어 들어올리기 효과를 적용합니다.주먹은 적군에게 근거리 공격 피해를 입히고 둔화 효과를 적용합니다. 적군은 이 공격을 방어할 수 있습니다.자신과 아군은 공중 제어가 증가합니다.","brief":"지면 주먹, 들어올리기·피해·둔화","short":"띄우기·둔화","tip":"주먹이 솟아오를 때 패리로 막을 수 있습니다"},{"slot":4,"en":"Goo Ball","ko":"끈적이 공","desc":"커다란 끈적이 공으로 변신하여 굴러다니며 피해를 입히고 적군과 충돌 시 적군을 기절시킵니다. 공으로 변신 시 총탄 및 마법 저항이 크게 증가합니다. 벽에 부딪혀 튕기거나 이중 점프를 할 수 있습니다.","brief":"변신해 굴러다님, 충돌 적 기절","short":"굴러 기절","tip":"공은 벽에 튕겨 다니니 벽 근처를 피하고 흩어지세요"}]},{"id":50,"en":"Pocket","ko":"포켓","aliases":["포켓","Pocket"],"role":"assassin","complexity":2,"style":"망토 순간이동과 가방 피신으로 치고 빠지는 근접 마법 암살자","tags":["순간이동","광역 마법","회피"],"laneStrength":"strong","spikes":"공중 폭격에 마력이 붙는 중반부터 한타 광역 피해가 크게 오릅니다. 고통의 흔적을 배우면 여러 명을 한 번에 깎아 놓을 수 있습니다.","strengths":["산탄총과 망토로 근거리 순간 화력이 강함","가방 피신으로 핵심 능력을 피할 수 있음","공중 폭격으로 뭉친 적을 넓게 둔화시킴"],"weaknesses":["체력이 낮아 먼저 물리면 쉽게 쓰러짐","멀리서는 산탄총 위력이 약함","공중 폭격 집중 중에는 움직임이 읽힘"],"vsTips":["산탄총 사거리 밖에서 거리를 두고 견제하세요","가방에 숨으면 주변에서 물러났다가 나올 때 공격하세요","망토가 날아오면 순간이동 위치를 예측해 미리 조준하세요"],"withTips":["포켓이 망토로 진입하면 바로 따라 들어가 화력을 보태세요","공중 폭격 둔화에 걸린 적을 우선 노리세요"],"plan":{"early":"산탄총과 망토로 짧게 견제하고 공중 폭격으로 트루퍼와 적을 함께 압박하세요.","mid":"망토 순간이동으로 측면에 진입해 뭉친 적에게 공중 폭격을 쏟아부으세요.","late":"고통의 흔적으로 적 전체를 깎은 뒤 가방으로 반격을 피하며 마무리하세요."},"core":["비행 망토를 던지고 그 위치로 순간이동해 산탄총 근접 사격","공중 폭격은 영웅 적중마다 피해 증가, 공중 시전 시 활공","맞을 땐 마법사의 가방으로 피신, 근처 적엔 고통의 흔적"],"counterItems":["Spirit Resilience","Silence Wave"],"confidence":"high","abilities":[{"slot":1,"en":"Barrage","ko":"공중 폭격","desc":"정신을 집중해 충돌 지점에 마법 피해를 입히고 둔화 효과를 적용하는 투사체를 날립니다. 투사체가 영웅에게 적중하면 포켓이 중첩되는 피해 증가를 얻습니다.공중에서 시전 시 포켓이 활공합니다.공중 대시나 비행 망토를 시전해도 포격이 중지되지 않습니다.","brief":"착탄 지점 피해·둔화, 적중 시 강화","short":"착탄 피해·둔화","tip":"폭격 낙하 지점에서 벗어나고 포켓 본체를 사격해 압박하세요"},{"slot":2,"en":"Flying Cloak","ko":"비행 망토","desc":"전방으로 이동하며 적군에게 피해를 입히는 영혼이 깃든 망토를 던집니다. 능력 2 키를 누르면 망토가 있는 위치로 순간이동할 수 있습니다.","brief":"망토 투척 피해, 망토 위치로 순간이동","short":"망토로 순간이동","tip":"망토가 날아간 끝에 포켓이 나타나니 그 위치를 조준해 두세요"},{"slot":3,"en":"Enchanter's Satchel","ko":"마법사의 가방","desc":"가방 속으로 피신합니다. 피신 지속 시간이 끝나면 근처 적군에게 마법 피해를 입힙니다. 다른 동작을 취하면 피신 상태가 종료됩니다.","brief":"피신 후 근처 적 마법 피해","short":"피신 후 피해","tip":"가방 근처에 서 있지 말고, 가방에서 나오는 순간을 노리세요"},{"slot":4,"en":"Affliction","ko":"고통의 흔적","desc":"주변 적군에게 지속 피해를 입힙니다.고통의 흔적 피해로 적군을 처치할 수 없으며 아이템 효과가 가중되지 않습니다.","brief":"주변 적 지속 피해(처치 불가)","short":"지속 피해","tip":"고통의 흔적만으로는 죽지 않지만 체력이 깎이니 바로 거리를 벌리세요"}]},{"id":52,"en":"Mirage","ko":"미라지","aliases":["미라지","Mirage"],"role":"assassin","complexity":2,"style":"회오리로 진입하고 표식 폭발로 마무리하는 기동형 총잡이","tags":["표식 폭발","생존력","글로벌 이동"],"laneStrength":"even","spikes":"진의 표식 업그레이드와 사격 아이템이 쌓이는 중반부터 표식 폭발 마무리가 위협적입니다. 여행자를 배우면 다른 전선 싸움에 빠르게 합류합니다.","strengths":["장수풍뎅이로 적 피해를 줄이고 체력을 흡수","회오리로 진입해 적을 띄워 연계가 쉬움","여행자로 어디든 빠르게 합류 가능"],"weaknesses":["회오리를 쓰고 나면 도주 수단이 부족함","여행자는 대기 중 피해를 받으면 끊김","확실한 군중 제어가 짧은 편"],"vsTips":["회오리 직후엔 총탄 회피가 생기니 능력으로 대응하세요","장수풍뎅이에 감염되면 정면 대결을 피하세요","미라지가 전선에서 사라지면 여행자 합류를 팀에 알리세요"],"withTips":["회오리로 뜬 적에게 바로 능력을 맞히세요","장수풍뎅이가 걸린 적을 함께 집중 공격하세요"],"plan":{"early":"장수풍뎅이로 체력을 유지하며 총으로 표식을 쌓아 견제하세요.","mid":"여행자로 다른 전선 싸움에 합류해 회오리로 열고 표식으로 마무리하세요.","late":"회오리로 적 후열을 띄우고 표식 폭발로 체력이 낮은 적을 끝내세요."},"core":["총탄마다 진의 표식 누적, 쌓일수록 표식 폭발 피해 배가","먼지 회오리로 진입해 띄우고, 이후 총탄 회피로 맞딜","여행자로 맵 어디든 순간이동해 아군 합류·기습"],"counterItems":["Healbane","Bullet Resilience"],"confidence":"high","abilities":[{"slot":1,"en":"Fire Scarabs","ko":"불꽃 장수풍뎅이","desc":"적군 한 명에게 불꽃 장수풍뎅이를 감염시킵니다. 감염된 적은 체력을 빼앗기고 입히는 피해가 감소합니다.","brief":"적 하나 체력 흡수·주는 피해 감소","short":"흡수·피해 감소","tip":"감염 중에는 내 피해가 줄어드니 효과가 끝날 때까지 물러나세요"},{"slot":2,"en":"Dust Devil","ko":"먼지 회오리","desc":"회오리로 변신합니다. 전방으로 이동하며 적군에게 피해를 입히고, 적군의 이동 속도를 둔화시키며, 공중으로 들어올립니다. 회오리가 끝나면 총탄 회피를 얻습니다.","brief":"회오리 돌진, 피해·둔화·띄우기","short":"돌진·띄우기","tip":"회오리가 다가오면 옆으로 피하고, 이후엔 총보다 능력으로 반격하세요"},{"slot":3,"en":"Djinn's Mark","ko":"진의 표식","desc":"활성 효과: 진의 표식을 모두 소모하여 즉시 피해를 입힙니다.","brief":"쌓인 표식 모두 터뜨려 즉시 피해","short":"쌓인 표식 폭발","tip":"표식이 쌓인 채로 오래 맞지 말고 엄폐물 뒤로 빠지세요"},{"slot":4,"en":"Traveler","ko":"여행자","desc":"미니맵의 한 위치를 대상으로 지정합니다. 잠시 후, 해당 위치로 순간 이동합니다. 대기 시간 동안 피해를 입으면 순간 이동이 중단됩니다.","brief":"미니맵 지점 순간이동, 피격 시 중단","short":"맵 순간이동","tip":"순간이동 대기 중인 미라지를 공격하면 이동을 끊을 수 있습니다"}]},{"id":58,"en":"Vyper","ko":"바이퍼","aliases":["바이퍼","Vyper"],"role":"assassin","complexity":1,"style":"단검 둔화와 맹독으로 약해진 적을 끝내는 암살형 사수","tags":["처형","둔화","기동"],"laneStrength":"strong","spikes":"치명적 맹독이 업그레이드되고 사격 아이템이 갖춰지면 체력이 깎인 적을 확실히 마무리합니다. 석화 올가미를 배우면 한타에서 핵심 적을 묶어 둘 수 있습니다.","strengths":["단검을 연속으로 맞히면 둔화가 크게 쌓임","맹독이 잃은 체력에 비례해 마무리에 강함","강화된 활주로 추격과 도주가 빠름"],"weaknesses":["단검을 못 맞히면 압박력이 크게 줄어듦","근접 난전에서 버티는 힘이 약함","석화를 잘못 쓰면 적이 피해를 막게 됨"],"vsTips":["엄폐물을 끼고 움직여 단검이 연속으로 맞지 않게 하세요","맹독이 걸리면 체력을 미리 채워 터지는 피해를 줄이세요","활주로 빠르게 파고드니 측면 진입을 항상 경계하세요"],"withTips":["석화된 적은 피해를 받지 않으니 풀린 직후에 공격하세요","단검 둔화가 쌓인 적을 함께 추격하세요"],"plan":{"early":"단검으로 적을 둔화시키고 총으로 견제하며 맹독 마무리 각을 노리세요.","mid":"활주로 측면에 돌아가 체력이 낮은 적을 맹독으로 끝내세요.","late":"올가미로 위협적인 적을 잠시 묶고 후열 딜러부터 정리하세요."},"core":["민첩 이동: 활주 거리↑·오르막 활주, 자주 미끄러져 속도 유지","활주 중 사격은 탄약이 안 줄어듦 → 미끄러지며 계속 난사","기습 단검 연속 적중으로 둔화, 도망치는 적은 치명적 맹독으로 마무리"],"counterItems":["Spirit Resilience","Debuff Reducer"],"confidence":"high","abilities":[{"slot":1,"en":"Screwjab Dagger","ko":"기습 단검","desc":"단검을 던져 마법 피해를 입히고 둔화를 적용합니다. 연속으로 같은 대상에게 단검이 적중할 때마다 마법 피해와 둔화가 중첩됩니다.","brief":"단검 피해·둔화, 연속 적중 시 중첩","short":"둔화 중첩","tip":"단검을 한 번 맞았다면 바로 엄폐해 중첩을 끊으세요"},{"slot":2,"en":"Lethal Venom","ko":"치명적 맹독","desc":"대상에 치명적인 맹독을 주입합니다. 맹독은 일정 시간 지연되었다가 발동하면서 마법 피해를 입힙니다. 대상이 잃은 체력만큼 피해가 증가합니다.치명적 맹독은 석화의 피해 차단을 무시합니다.","brief":"지연 독, 잃은 체력 비례 피해","short":"잃은 체력 독","tip":"맹독이 터지기 전에 체력을 회복하거나 거리를 벌리세요"},{"slot":3,"en":"Slither","ko":"민첩 이동","desc":"활주 거리가 증가하고, 활주하여 오르막길을 오를 수 있으며, 활주 시 방향을 더 빠르게 전환합니다.","brief":"활주 거리 증가·오르막 활주","short":"활주 강화","tip":"활주로 언덕도 오르니 고지대에 있어도 방심하지 마세요"},{"slot":4,"en":"Petrifying Bola","ko":"석화 올가미","desc":"폭발하는 올가미를 투척합니다. 폭발 시 영역 내에 있는 모든 적군은 둔화되고 피해를 입습니다.올가미에 적중당한 적군은 추가 피해를 입고 석화됩니다. 석화된 유닛은 모든 피해를 차단하지만, 동작을 취할 수 없습니다.","brief":"광역 피해·둔화, 직격 시 석화","short":"광역 둔화·석화","tip":"올가미 폭발 범위를 벗어나고, 석화가 풀린 직후 반격을 준비하세요"}]},{"id":60,"en":"Sinclair","ko":"싱클레어","aliases":["싱클레어","Sinclair"],"role":"mystic","complexity":4,"style":"토끼 주술과 궁극기 복사로 변수를 만드는 견제형 마법사","tags":["견제","군중 제어","궁극기 복사"],"laneStrength":"even","spikes":"토끼 주술 업그레이드 후 한타 제어력이 크게 오릅니다. 복사술은 상대에게 강한 궁극기가 많을수록 가치가 커집니다.","strengths":["혼란의 번개로 먼 거리 견제가 강함","토끼 주술로 여러 명을 한 번에 무력화함","조수와 위치를 바꿔 위기를 벗어남"],"weaknesses":["능력 의존도가 높아 쿨다운 중엔 약함","조작이 어려워 실수하기 쉬움","몸이 약해 기습에 취약함"],"vsTips":["번개는 멀리 날수록 아프니 엄폐하거나 거리를 좁히세요","조수를 먼저 없애 추가 피해와 위치 교체를 끊으세요","토끼가 되면 빨라진 이동 속도로 일단 아군 쪽으로 물러나세요"],"withTips":["토끼가 된 적은 피해를 더 받으니 바로 집중 사격하세요","싱클레어가 복사한 궁극기에 맞춰 진입 타이밍을 맞추세요"],"plan":{"early":"혼란의 번개로 적을 꾸준히 깎고 조수로 사격 피해를 더하세요.","mid":"토끼 주술로 적을 묶어 팀원과 함께 킬을 만드세요.","late":"가장 위협적인 적 궁극기를 복사해 한타 흐름을 뒤집으세요."},"core":["유령 조수를 깔면 함께 공격, 조수와 위치 교체로 탈출","혼란의 번개는 멀리 날수록 강해지고 비행 중 방향 전환 가능","토끼 주술로 적 무력화, 복사술로 적 궁극기를 빌려 사용"],"counterItems":["Spirit Resilience","Debuff Reducer"],"confidence":"high","abilities":[{"slot":1,"en":"Vexing Bolt","ko":"혼란의 번개","desc":"마법 번개를 발사하여 피해를 입힙니다. 피해량은 날아가는 동안 증가합니다. 조수가 있는 경우 조수도 감소된 피해를 입히는 번개를 발사합니다. 능력 1 키를 누르면 조준선이 있는 위치로 번개가 날아가는 방향을 전환할 수 있습니다.","brief":"날수록 강해지는 번개, 방향 전환","short":"날수록 강해짐","tip":"번개는 멀리서 강해지니 엄폐하거나 가까이 붙으세요"},{"slot":2,"en":"Spectral Assistant","ko":"유령 조수","desc":"대상 위치에 조수를 소환합니다. 조수는 영웅이 사격할 때마다 함께 공격하며 피해를 입힙니다.조수가 소환되어 있으면 능력 2 키를 눌러 조수와 위치를 교체할 수 있습니다.유령 조수 시전 시 무기가 재장전됩니다.","brief":"사격 따라 공격하는 조수·위치 교체","short":"따라 쏘기·위치 교체","tip":"조수가 보이면 먼저 쏴서 없애세요"},{"slot":3,"en":"Rabbit Hex","ko":"토끼 주술","desc":"대상 지역에 주술을 걸어 일정 시간 동안 모든 적군을 토끼로 변신시킵니다.대상이 작은 토끼로 변하면 이동 속도가 증가하고 추가 피해를 입으며 거의 모든 동작을 취할 수 없습니다.주술은 능력을 방해하지 않습니다.","brief":"범위 내 적 토끼로 변신","short":"적을 토끼로","tip":"토끼가 되면 빨라진 속도로 아군 쪽으로 도망치세요"},{"slot":4,"en":"Audience Participation","ko":"복사술","desc":"제한된 시간 동안 적군 영웅의 궁극기를 복사합니다. 능력을 다시 활성화하면 복사한 궁극기를 대신 사용합니다.복사한 궁극기는 해당 능력의 업그레이드 포인트를 그대로 받습니다.복사술은 쿨다운도 복사합니다.","brief":"적 영웅 궁극기 복사해 사용","short":"적 궁극기 사용","tip":"내 궁극기가 복사될 수 있으니 복사술 이후엔 내 궁극기를 경계하세요"}]},{"id":63,"en":"Mina","ko":"미나","aliases":["미나","Mina"],"role":"marksman","complexity":3,"style":"총탄 추가 마법 피해와 박쥐 침묵을 쓰는 사수","tags":["마법 총탄","침묵","회피"],"laneStrength":"even","spikes":"영웅에게 사랑의 고통을 여러 번 터뜨려 박쥐 수가 늘어날수록 녹스 노스트라가 강해집니다. 중반 이후 궁극기 침묵이 한타를 좌우합니다.","strengths":["총탄에 마법 피해가 붙어 꾸준히 딜함","피의 퇴각으로 위험에서 빠르게 이탈","박쥐 침묵으로 여러 적의 능력을 막음"],"weaknesses":["퇴각을 쓰고 나면 도주 수단이 부족함","궁극기가 강해지기까지 시간이 걸림","가까이 붙으면 버티기 어려움"],"vsTips":["피의 퇴각이 빠진 걸 확인하고 진입하세요","능력에 연달아 맞으면 사랑의 고통이 터지니 짧게 교전하세요","박쥐가 오면 침묵에 걸리기 전에 중요한 능력을 먼저 쓰세요"],"withTips":["미나의 박쥐 침묵에 맞춰 함께 진입하세요","미나가 퇴각으로 빠지면 무리하지 말고 같이 물러나세요"],"plan":{"early":"총탄 추가 피해로 견제하고 능력을 섞어 사랑의 고통을 터뜨리세요.","mid":"영웅에게 사랑의 고통을 자주 터뜨려 박쥐 수를 늘리세요.","late":"녹스 노스트라 침묵으로 한타를 열고 퇴각으로 안전하게 빠지세요."},"core":["총탄·능력으로 사랑의 고통 폭발을 터뜨리는 게 핵심 딜","피의 퇴각으로 치고 빠지는 유리대포, 갈퀴로 근접 마무리","사랑의 고통 발동마다 녹스 노스트라 박쥐 수 영구 증가"],"counterItems":["Debuff Reducer","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Rake","ko":"갈퀴","desc":"우산으로 앞을 베어 마법 피해를 줍니다. 영웅에게는 잃은 체력에 비례한 추가 피해를 주고, 처치할 때마다 체력을 회복합니다. 체력이 낮은 트루퍼·중립 유닛은 바로 처치합니다. 패시브: 공중에서 보조 사격(확대)을 누르고 있으면 최대 4초 동안 떠 있습니다.","brief":"전방 베기, 잃은 체력 비례 추가 피해","short":"처형 베기","tip":"갈퀴 이후 이어지는 연계를 경계하며 거리를 유지하세요"},{"slot":2,"en":"Sanguine Retreat","ko":"피의 퇴각","desc":"잠시 흩어져 대상 지정 불가 상태가 되고 목표 지점으로 날아갑니다. 짧은 시간 내에 다시 시전할 수 있습니다.","brief":"대상 지정 불가 상태로 날아 이동","short":"지정 불가 이동","tip":"퇴각 중엔 공격이 통하지 않으니 도착 지점을 노리세요"},{"slot":3,"en":"Love Bites","ko":"사랑의 고통","desc":"총탄이 추가 마법 피해를 입힙니다. 능력으로 피해를 입히면 잔인한 고통이 중첩되며, 폭발적인 보너스 마법 피해를 입힙니다. 사랑의 고통은 대상마다 별도의 쿨다운이 적용됩니다.","brief":"총탄 추가 피해·능력 중첩 시 폭발","short":"중첩 폭발","tip":"능력에 연달아 맞지 않게 짧게 치고 빠지세요"},{"slot":4,"en":"Nox Nostra","ko":"녹스 노스트라","desc":"활성 효과: 대상을 찾아가는 박쥐 무리를 내보냅니다. 각 박쥐는 마법 피해를 입히고 침묵 효과를 적용합니다.지속 효과: 영웅을 대상으로 사랑의 고통 발동 시 내보내는 박쥐의 수가 영구적으로 증가합니다.","brief":"추적 박쥐 무리, 피해·침묵","short":"박쥐·침묵","tip":"박쥐가 날아오면 엄폐물 뒤로 숨어 침묵을 피하세요"}]},{"id":64,"en":"Drifter","ko":"드리프터","aliases":["드리프터","Drifter"],"role":"assassin","complexity":3,"style":"출혈 표식으로 등 뒤를 잡고 어둠 속에 고립시키는 근접 암살자","tags":["근접","순간이동","고립"],"laneStrength":"even","spikes":"추격자의 표식과 할퀴기 연계가 갖춰지면 혼자 다니는 적을 빠르게 잡습니다. 영원의 밤을 배우면 한타에서 적을 갈라놓을 수 있습니다.","strengths":["표식 후 등 뒤로 순간이동해 기습함","근거리에서 할퀴기 추가 피해가 큼","궁극기로 적의 시야를 크게 막음"],"weaknesses":["표식이 빗나가면 진입 수단이 줄어듦","멀리서 견제하는 적에게 약함","근접해야 해서 군중 제어에 취약함"],"vsTips":["표식 투사체를 피하면 순간이동 기습을 막을 수 있어요","출혈 중이면 등 뒤 기습에 대비해 아군 곁에 붙으세요","영원의 밤에 걸리면 혼자 움직이지 말고 아군 쪽으로 모이세요"],"withTips":["드리프터가 등 뒤로 넘어가면 정면에서 같이 압박하세요","영원의 밤으로 시야가 막힌 적을 집중 공격하세요"],"plan":{"early":"할퀴기와 표식으로 짧게 교환하고 출혈 상태일 때 뒤를 잡아 압박하세요.","mid":"혼자 다니는 적을 표식으로 노려 빠르게 잡아내세요.","late":"영원의 밤으로 적을 고립시킨 뒤 핵심 딜러부터 처리하세요."},"core":["혈향으로 고립된 적을 추적, 고립 대상에게 피해 증가","추격자의 표식 출혈 중 재발동 → 적 등 뒤로 순간 습격","영원의 밤으로 적 시야를 가리고 전원 고립시켜 사냥"],"counterItems":["Spirit Resilience","Debuff Reducer"],"confidence":"low","abilities":[{"slot":1,"en":"Rend","ko":"할퀴기","desc":"전방 공격 영역 내의 적군을 할퀴고, 마법 피해를 입힙니다. 적군이 근거리 내에 있다면, 보너스 근거리 공격 피해를 입힙니다.","brief":"전방 범위 피해, 근접 시 추가 피해","short":"근접 추가 피해","tip":"할퀴기는 가까울수록 아프니 붙지 말고 거리를 유지하세요"},{"slot":2,"en":"Stalker's Mark","ko":"추격자의 표식","desc":"표식을 날려 첫 번째로 적중한 대상에게 출혈을 일으켜 지속 마법 피해를 입힙니다. 적군이 출혈 상태일 때 추격자의 표식을 다시 발동하면, 즉시 대상의 뒤에서 습격합니다.","brief":"출혈 표식, 재시전 시 뒤로 습격","short":"출혈·뒤로 습격","tip":"표식에 맞아 출혈 중이면 뒤에서 나타날 드리프터를 대비하세요"},{"slot":3,"en":"Bloodscent","ko":"혈향","desc":"패시브: 고립된 적 영웅은 이동 흔적과 심장 소리를 남깁니다. 고립된 영웅에게 주는 피해가 늘고, 근처에서 고립된 영웅이 죽으면 무기 피해가 영구히 오릅니다. 사용: 감각을 끌어올려 근처 영웅에게 이어지는 흔적을 드러냅니다.","brief":"고립된 적 추적·주는 피해 증가","short":"고립 추적","tip":"체력이 낮을 때는 드리프터 근처에 혼자 남지 마세요"},{"slot":4,"en":"Eternal Night","ko":"영원의 밤","desc":"근처 적군 영웅들을 어둠 속에 가두어 시야를 대폭 제한합니다. 영향을 받은 적군은 잠시 모습이 노출되며 지속 시간 동안 고립 상태로 간주됩니다.자신은 추가 질주 속도를 얻습니다.","brief":"근처 적 시야 제한·고립 상태","short":"시야 차단","tip":"어둠에 갇히면 미니맵과 소리를 참고해 아군 쪽으로 이동하세요"}]},{"id":65,"en":"Venator","ko":"베네터","aliases":["베네터","Venator"],"role":"marksman","complexity":2,"style":"덫과 벽 기절로 묶고 석궁 처형으로 끝내는 사수","tags":["처형","치유 감소","제어"],"laneStrength":"even","spikes":"거룩한 분노를 배운 뒤부터 체력이 낮은 적을 멀리서도 처형할 수 있습니다. 사격 아이템이 쌓일수록 말뚝 한 발의 위력이 커집니다.","strengths":["유탄 화상으로 적의 치유를 줄임","벽 근처의 적을 복부 사격으로 기절시킴","궁극기 마지막 말뚝으로 처형 가능"],"weaknesses":["덫과 유탄 위치가 읽히면 효과가 떨어짐","기동기가 부족해 기습에 약함","궁극기를 빗맞히면 위력이 크게 줄어듦"],"vsTips":["벽을 등지고 싸우지 말고 트인 곳에서 상대하세요","걷어찬 덫은 잠시 뒤 작동하니 덫 근처를 피해 다니세요","체력이 낮으면 석궁 처형을 피해 시야에서 벗어나세요"],"withTips":["불붙은 적은 치유가 줄어드니 그때 집중 공격하세요","덫에 묶인 적에게 바로 능력을 퍼부으세요"],"plan":{"early":"유탄과 산탄 사격으로 견제하고 적을 벽 쪽으로 몰아 기절을 노리세요.","mid":"덫으로 길목을 막고 걸린 적을 팀과 함께 잡으세요.","late":"한타 뒤 체력이 낮은 적을 거룩한 분노 말뚝으로 처형하세요."},"core":["축성 유탄으로 불붙여 치유 감소, 주술 각인 곰덫으로 묶기","복부 사격으로 적을 벽 쪽으로 밀면 기절·추가 피해","거룩한 분노 석궁 3발, 마지막 발은 체력 낮은 적 처형"],"counterItems":["Bullet Resilience","Metal Skin"],"confidence":"low","abilities":[{"slot":1,"en":"Consecrating Grenade","ko":"축성 유탄","desc":"유탄을 발사합니다. 유탄은 한 번 튕긴 뒤 폭발하여 무기 피해를 입히고 적군에게 불을 붙입니다.불타는 대상은 구역 내 적군에게 순수 피해를 입히며 받는 치유량이 감소합니다.","brief":"튕기는 유탄, 피해·화상·치유 감소","short":"화상·치유 감소","tip":"불이 붙으면 주변 아군도 피해를 받으니 서로 흩어지세요"},{"slot":2,"en":"Gutshot","ko":"복부 사격","desc":"산탄총으로 강력한 사격을 가해 무기 피해를 입히고 적군을 뒤로 밀어냅니다. 벽 근처에 있는 적군은 기절하고 보너스 무기 피해를 입습니다.","brief":"산탄 밀쳐내기, 벽에 박으면 기절","short":"밀쳐내기·기절","tip":"벽을 등지고 서지 마세요"},{"slot":3,"en":"Hex-Lined Snap Trap","ko":"주술 각인 곰덫","desc":"짧은 지연 시간 후 활성화되는 트랩을 전방으로 걷어찹니다.트랩은 처음 닿은 적군에게 튀어 올라 마법 피해를 입히고, 이동 불가 효과를 적용하며, 이후 일정 시간 동안 적군을 드러냅니다.","brief":"덫 투척, 밟은 적 이동 불가·노출","short":"이동 불가·노출","tip":"덫에 걸리면 위치가 드러나니 풀리자마자 엄폐하세요"},{"slot":4,"en":"Ira Domini","ko":"거룩한 분노","desc":"석궁에 매우 강력한 무기 피해를 입히는 말뚝 3개를 장전합니다.마지막 말뚝은 축복을 받으며, 보너스 순수 피해를 입히고 체력이 낮은 적군을 처형합니다.","brief":"강한 말뚝 3발, 마지막 발 처형","short":"말뚝 처형","tip":"석궁을 들면 체력이 낮은 상태로 정면에 서지 마세요"}]},{"id":66,"en":"Victor","ko":"빅터","aliases":["빅터","Victor"],"role":"brawler","complexity":2,"style":"스스로 고통을 견디며 오라로 주변을 태우는 근접 싸움꾼","tags":["지속 피해","부활","탱킹"],"laneStrength":"even","spikes":"충격 부활을 배운 뒤로는 죽을 위기에서도 되살아나 반격합니다. 체력과 재생 아이템이 쌓이면 고통의 오라를 오래 유지할 수 있습니다.","strengths":["궁극기로 치명상을 입어도 되살아남","고통의 오라로 주변 적을 계속 깎음","심장 충격기로 재생과 이동 속도를 얻음"],"weaknesses":["능력이 자신에게도 피해를 줌","멀리서 견제당하면 일방적으로 맞음","부활 직후 집중 공격에 다시 쓰러짐"],"vsTips":["오라를 켜면 거리를 벌려 빅터 스스로 깎이게 만드세요","쓰러뜨린 직후 부활 기절이 오니 곧바로 붙지 마세요","배터리는 맞을수록 차니 짧고 굵게 교환하세요"],"withTips":["빅터가 오라로 버티는 동안 뒤에서 화력을 보태세요","부활 기절에 걸린 적을 바로 공격하세요"],"plan":{"early":"고통의 오라로 트루퍼와 적을 함께 압박하고 심장 충격기로 체력을 회복하세요.","mid":"체력 아이템을 갖추고 한타 앞에서 오라로 버티며 적을 깎으세요.","late":"충격 부활을 믿고 깊게 진입해 적의 집중 포화를 받아내세요."},"core":["맞을수록 고통의 배터리 충전 → 가득 차면 감전 볼트 발사","심장 충격기로 자해해 재생·이속, 고통의 오라로 붙어 지속딜","죽어도 충격 부활로 되살아나 주변 기절, 앞에서 과감히 버티기"],"counterItems":["Healbane","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Pain Battery","ko":"고통의 배터리","desc":"피해를 입으면 고통의 배터리가 서서히 충전됩니다. 완전히 충전되면 능력을 사용해 여러 개의 감전 볼트를 발사하고, 대상당 한 번씩 마법 피해를 입힙니다.","brief":"피격 충전 후 감전 볼트 발사","short":"감전 볼트","tip":"빅터를 오래 때리면 배터리가 차니 한 번에 몰아치세요"},{"slot":2,"en":"Jumpstart","ko":"심장 충격기","desc":"자신에게 마법 피해를 입히고, 보너스 재생 및 추가 이동 속도를 얻습니다. 이 효과는 점차 감소합니다.","brief":"자해 후 재생·이동 속도 증가","short":"자해 재생","tip":"충격기를 쓴 빅터는 빨라지니 무리한 추격은 피하세요"},{"slot":3,"en":"Aura of Suffering","ko":"고통의 오라","desc":"적군과 자신 모두에게 지속 마법 피해를 입히는 고통을 발산합니다. 능력을 시전하는 동안, 최대치에 도달할 때까지 피해가 계속 증가합니다.","brief":"적·자신 지속 피해, 점점 증가","short":"적·자신 지속 피해","tip":"오라 범위 밖에서 싸우세요"},{"slot":4,"en":"Shocking Reanimation","ko":"충격 부활","desc":"죽음에 달하는 피해를 입으면, 파동을 방출해 서서히 효과가 감소하는 둔화를 적용합니다.짧은 능력 집중 후 되살아나서 근처 적에게 마법 피해를 입히고 기절 효과를 적용합니다.","brief":"사망 시 부활, 근처 적 피해·기절","short":"사망 시 부활","tip":"쓰러뜨린 뒤 되살아날 때 근처에서 떨어지세요"}]},{"id":67,"en":"Paige","ko":"페이지","aliases":["페이지","Paige"],"role":"mystic","complexity":1,"style":"아군에게 방벽을 주고 맵 전체를 지원하는 서포터형 마법사","tags":["지원","방벽","글로벌 궁극기"],"laneStrength":"even","spikes":"기사의 돌격을 배우면 맵 전체에 치유와 피해를 줄 수 있어 모든 전선에 영향을 줍니다. 주인공 보정이 강화되면 아군 딜러의 싸움을 크게 돕습니다.","strengths":["주인공 보정으로 아군을 지키고 강화함","매력적인 독서로 적을 묶어 연계가 쉬움","궁극기로 맵 전체를 치유하고 공격함"],"weaknesses":["혼자서는 킬을 내는 힘이 약함","이동기가 없어 기습에 취약함","지연 폭발 능력이라 피하기 쉬움"],"vsTips":["독서 마법에 걸리면 폭발 전에 범위를 벗어나세요","방벽을 받은 적은 무기 피해가 오르니 방벽부터 깨세요","용이 지나간 불길 위에 서 있지 마세요"],"withTips":["주인공 보정을 받으면 무기 피해가 오르니 그때 공격적으로 싸우세요","독서 폭발로 적이 묶이는 타이밍에 진입하세요"],"plan":{"early":"아군에게 주인공 보정을 걸어 교환을 유리하게 만들고 용으로 견제하세요.","mid":"독서로 적을 묶어 아군이 킬을 내도록 도우세요.","late":"기사의 돌격으로 먼 아군을 치유하고 한타 전에 적 체력을 깎으세요."},"core":["주인공 보정으로 아군에게 방벽+무기 피해 부여","책 속의 용·매력적인 독서로 원거리 견제와 이동 불가","기사의 돌격은 맵 전체 지원, 멀리 갈수록 치유·피해 증가"],"counterItems":["Healbane","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Bookwyrm","ko":"책 속의 용","desc":"대상 위치에서 전방으로 날아가는 용을 소환합니다. 용은 마법 피해를 입히고 지나간 자리에 불타는 길을 남깁니다.","brief":"전방으로 나는 용, 피해·불길 남김","short":"용 브레스","tip":"용이 날아가는 경로와 남은 불길을 옆으로 피하세요"},{"slot":2,"en":"Plot Armor","ko":"주인공 보정","desc":"아군에게 방벽을 부여합니다. 방벽이 유지되는 동안에는 보너스 무기 피해를 얻습니다.","brief":"아군 방벽·무기 피해 증가","short":"아군 방벽","tip":"방벽이 있는 적과 정면으로 싸우지 말고 방벽이 사라진 뒤 싸우세요"},{"slot":3,"en":"Captivating Read","ko":"매력적인 독서","desc":"대상 지역에 마법을 걸어 둔화 효과를 적용합니다.마법은 일정 지연 시간 후 폭발해 마법 피해를 입히고 이동 불가 효과를 적용합니다.","brief":"지역 둔화 후 폭발, 피해·이동 불가","short":"지역 속박","tip":"둔화가 걸리면 곧 이동 불가가 오니 바로 범위 밖으로 나가세요"},{"slot":4,"en":"Rallying Charge","ko":"기사의 돌격","desc":"도시 전체를 질주하는 망령 기사와 군마를 해방합니다. 망령 기사와 군마는 아군을 치유하고 적군에게는 마법 피해를 입힙니다. 망령 기사와 군마가 더 멀리 이동할수록 치유 능력 및 마법 피해가 증폭됩니다.","brief":"맵 질주 기사, 아군 치유·적 피해","short":"아군 치유·적 피해","tip":"기사는 멀리서 올수록 강하니 체력이 낮으면 경로에서 비켜서세요"}]},{"id":69,"en":"The Doorman","ko":"도어맨","aliases":["도어맨","The Doorman"],"role":"mystic","complexity":1,"style":"문과 카트로 전장을 비틀고 적을 호텔로 보내는 변칙형 마법사","tags":["제어","이동 지원","격리"],"laneStrength":"even","spikes":"호텔 손님을 배우면 핵심 적을 잠시 전장에서 빼낼 수 있어 한타가 쉬워집니다. 문 연결은 아군의 기습과 퇴각 모두에 큰 힘이 됩니다.","strengths":["호출 벨로 적의 명중률과 이동을 떨어뜨림","문 연결로 아군의 이동 경로를 만듦","궁극기로 적 한 명을 전장에서 빼냄"],"weaknesses":["직접 딜 능력이 상대적으로 약함","문 위치가 들키면 적도 이용할 수 있음","능력이 빠지면 몸싸움에 약함"],"vsTips":["호출 벨이 터지기 전에 범위에서 벗어나세요","도어맨의 문은 나도 지나갈 수 있으니 역으로 활용하세요","호텔로 보내지면 곧장 출구 엘리베이터로 달려가세요"],"withTips":["도어맨이 문을 깔면 그 문으로 기습하거나 빠져나가세요","카트에 끌려온 적을 바로 집중 공격하세요"],"plan":{"early":"호출 벨로 적의 명중률을 떨어뜨리고 카트로 끌어와 아군과 함께 공격하세요.","mid":"문 연결로 아군의 기습 경로를 만들어 다른 전선 싸움을 도우세요.","late":"가장 위험한 적을 호텔로 보내고 그 사이 한타를 이기세요."},"core":["문 연결로 아군 이동·기습 경로 만들기, 투사체도 통과","수하물 카트로 적을 끌고 가거나 아군에게 써서 구출","호텔 손님으로 핵심 적을 전장에서 잠시 빼내기"],"counterItems":["Debuff Reducer","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Call Bell","ko":"호출 벨","desc":"충돌 시 마법 피해를 입히는 호출 벨을 던집니다. 호출 벨은 짧은 지연 시간 후 폭발하며, 추가 마법 피해를 입히고 적중한 적에게 무기 명중률 감소 효과와 이동 속도 둔화 효과를 적용합니다.호출 벨을 사격하여 원하는 시점에 폭발시킬 수 있습니다.","brief":"벨 투척·폭발, 피해·둔화·명중률 감소","short":"벨 폭발","tip":"벨이 떨어진 곳을 바로 벗어나 둔화와 명중률 감소를 피하세요"},{"slot":2,"en":"Doorway","ko":"문 연결","desc":"서로 연결된 두 개의 문을 배치합니다. 플레이어와 대다수의 투사체는 한쪽 문으로 들어간 뒤 다른 쪽 문을 통해 나올 수 있습니다. 문은 지속 시간이 끝나면 닫힙니다.두 개의 문은 일정 거리 내에서만 배치할 수 있습니다.","brief":"연결된 두 문 배치, 통과 이동","short":"두 문 사이 이동","tip":"투사체가 반대편 문으로 나올 수 있으니 양쪽 문을 모두 경계하세요"},{"slot":3,"en":"Luggage Cart","ko":"수하물 카트","desc":"마법 피해를 입히고 경로에 있는 적군 영웅에게 끌어당기기 효과를 적용하는 수하물 카트를 날려 보냅니다. 키로 대체 시전하여, 아군 영웅을 대상으로 사용할 수 있습니다.","brief":"카트 돌진, 적 피해·끌어당김","short":"돌진·끌어당김","tip":"카트 경로에서 옆으로 비켜서세요"},{"slot":4,"en":"Hotel Guest","ko":"호텔 손님","desc":"대상의 육신을 남작 부인 호텔의 손님으로 보냅니다. 손님은 곧장 탈출 엘리베이터를 찾아 이동해야 하며, 엘리베이터에 도착하면 원래 위치로 돌아올 수 있습니다. 남작 호텔에 머무는 비용은 마법 피해로 지불하게 됩니다. 제시간에 체크아웃하지 못할 시 추가 마법 피해가 부과됩니다.","brief":"대상 호텔로 보내 마법 피해","short":"호텔로 추방","tip":"호텔에서는 머뭇거리지 말고 곧장 출구를 찾아 이동하세요"}]},{"id":72,"en":"Billy","ko":"빌리","aliases":["빌리","Billy"],"role":"brawler","complexity":3,"style":"방망이 근거리 공격과 사슬로 적을 붙잡는 돌격형 싸움꾼","tags":["근접","돌진","광역 제어"],"laneStrength":"strong","spikes":"사슬 포획을 배운 뒤로 여러 적을 한 번에 묶고 끌어올 수 있어 한타 개시가 강해집니다. 근접 아이템이 갖춰지면 근거리 공격 압박이 매우 강해집니다.","strengths":["들이받기로 빠르게 붙어 적을 띄움","근거리 공격으로 탄약을 회복해 교전이 길어도 강함","사슬로 적의 이동 능력을 막음"],"weaknesses":["붙어야 해서 원거리 견제에 약함","돌진이 빗나가면 진입이 어려워짐","둔화와 군중 제어에 크게 약함"],"vsTips":["들이받기 사거리 밖에서 견제하세요","근거리 공격에 맞으면 파쇄 상태가 되니 붙지 마세요","사슬에 묶이면 엄폐물 뒤로 돌아가 시야를 끊으세요"],"withTips":["빌리가 적을 띄우면 공중에 뜬 적에게 바로 사격하세요","사슬로 끌려온 적들에게 광역 능력을 맞히세요"],"plan":{"early":"들이받기와 근거리 공격으로 적에게 붙어 짧고 강하게 교환하세요.","mid":"들이받기로 혼자 있는 적을 띄워 팀과 함께 잡아내세요.","late":"사슬 포획으로 적 여러 명을 묶고 아군 화력 쪽으로 끌어오세요."},"core":["들이받기로 붙고 내려찍기로 끌어내린 뒤 근접 난타","근접 적중 시 탄약 회복·파쇄 부여, 폭주로 파쇄 적에 총탄 강화","사슬 포획으로 주변 적 이동기를 막고 한꺼번에 끌어오기"],"counterItems":["Slowing Hex","Unstoppable"],"confidence":"low","abilities":[{"slot":1,"en":"Bashdown","ko":"내려찍기","desc":"방망이를 땅에 내려찍고 적군에게 끌어당기기 효과를 적용하고 근거리 공격 피해를 입힙니다.충격은 파동을 일으키며, 마법 피해를 입히고 들어올리기 효과를 적용합니다.","brief":"내려찍어 끌어당김·피해·띄우기","short":"끌어당겨 띄우기","tip":"내려찍기 범위 안에 있지 말고, 띄워진 뒤 이어지는 연계를 조심하세요"},{"slot":2,"en":"Rising Ram","ko":"들이받기","desc":"적군을 향해 머리부터 들이받아 빌리와 함께 공중으로 날려 보냅니다.충돌 시 쿨다운이 50% 감소합니다.","brief":"적에게 돌진해 함께 띄우기","short":"돌진해 띄우기","tip":"들이받기가 오면 옆으로 피하세요"},{"slot":3,"en":"Blasted","ko":"폭주","desc":"지속 효과: 근거리 공격을 가하면 탄약을 회복하고 7.0초 동안 대상에게 파쇄 상태를 부여합니다.","brief":"근거리 공격 시 탄약 회복·파쇄","short":"근접 탄약 회복","tip":"근거리 공격을 맞지 않게 거리를 유지하세요"},{"slot":4,"en":"Chain Gang","ko":"사슬 포획","desc":"주변 적군을 사슬로 묶습니다. 묶인 적은 이동 능력을 사용할 수 없으며, 묶인 적이 사슬을 당기면 강한 둔화 효과를 받습니다.잠시 후, 묶인 모든 적군을 빌리에게 끌어당기며 마법 피해를 입힙니다.적군이 일정 시간 동안 시야 밖으로 나가면 사슬이 끊어집니다.","brief":"주변 적 사슬 묶기 후 끌어당김","short":"묶어 끌어당김","tip":"사슬은 시야가 한동안 끊기면 풀리니 벽 뒤로 돌아가세요"}]},{"id":76,"en":"Graves","ko":"그레이브즈","aliases":["그레이브즈","Graves"],"role":"mystic","complexity":2,"style":"죽음을 모아 언데드를 부리고 저항을 빼앗는 소환형 마법사","tags":["소환","이동 불가","약화"],"laneStrength":"even","spikes":"주변에서 죽음을 많이 모을수록 죽음의 단지가 위협적입니다. 정수 강탈이 쌓이는 긴 교전일수록 유리합니다.","strengths":["데드헤드로 꾸준한 마법 피해를 줌","속박의 손으로 길목을 막고 적을 묶음","사격으로 적의 피해와 마법 저항을 빼앗음"],"weaknesses":["주변에 죽음이 없으면 단지를 쓰기 어려움","속박의 손은 위치가 보여 피하기 쉬움","기동기가 부족해 기습에 약함"],"vsTips":["속박의 손 균열은 돌아가거나 사라진 뒤 지나가세요","데드헤드는 그레이브즈의 사격 대상을 노리니 표적이 되면 물러나세요","오래 맞을수록 저항을 빼앗기니 짧게 교전하세요"],"withTips":["트루퍼를 함께 정리해 단지에 죽음을 모아주세요","속박의 손에 묶인 적에게 집중 사격하세요"],"plan":{"early":"트루퍼를 처치해 죽음을 모으고 단지로 적과 트루퍼를 함께 압박하세요.","mid":"속박의 손으로 길목을 막아 팀의 기습과 추격을 도우세요.","late":"데드헤드와 강탈로 적 저항을 깎으며 후방에서 꾸준히 피해를 주세요."},"core":["근처에서 죽음이 생기면 죽음의 단지 충전 → 던져 데드헤드 소환","정수 강탈: 계속 쏘면 적의 무기 피해·마법 저항을 빼앗음","능력으로 구울을 불러 압박, 속박의 손 균열로 길목 차단"],"counterItems":["Spirit Resilience","Debuff Reducer"],"confidence":"low","abilities":[{"slot":1,"en":"Jar of Dead","ko":"죽음의 단지","desc":"지속 효과: 근처에서 무엇이든 사망하면 죽음의 기운을 거두고 죽음의 단지에 저장합니다.활성 효과: 단지를 던져 데드헤드를 소환합니다. 데드헤드는 적군에게 지속적으로 마법 피해를 입힙니다.데드헤드는 근처에 적군이 없을 때 플레이어를 따라다니며, 플레이어의 무기가 노리는 대상을 우선 공격합니다.","brief":"모은 죽음 기운으로 데드헤드 소환","short":"데드헤드 소환","tip":"데드헤드가 소환되면 그 자리에서 빠져나오세요"},{"slot":2,"en":"Grasping Hands","ko":"속박의 손","desc":"속박의 손을 일렬로 솟아오르게 하여, 구울을 소환하고 균열을 남깁니다. 균열을 통과하는 적군은 마법 피해를 입고 이동 불가 효과를 받습니다.대체 시전 : 장벽의 방향을 회전합니다.","brief":"구울·균열 소환, 통과 적 이동 불가","short":"이동 불가 손","tip":"손이 솟은 균열 위를 지나가지 마세요"},{"slot":3,"en":"Essence Theft","ko":"정수 강탈","desc":"무기 공격이 시간이 지남에 따라 무기 피해 및 마법 저항을 강탈합니다. 대상당 최대치가 존재합니다.","brief":"사격으로 무기 피해·마법 저항 강탈","short":"마법 저항 강탈","tip":"그레이브즈에게 오래 맞지 말고 엄폐해 강탈을 끊으세요"},{"slot":4,"en":"Borrowed Decree","ko":"빌려온 칙령","desc":"지정한 곳에 묘비를 세워 16초 동안 구울을 계속 불러냅니다. 구울은 적 기지 쪽으로 걸어가다 영웅이나 오브젝트에 다가가면 폭발해 범위 마법 피해와 짧은 둔화를 줍니다. 묘비는 미니맵과 벽 너머로 보이며, 적이 강한 근거리 공격 두 번으로 부술 수 있습니다.","brief":"묘비에서 자폭 구울 계속 소환","short":"자폭 구울","tip":"궁극기가 준비됐을 땐 체력을 넉넉히 유지하고 거리를 두세요"}]},{"id":77,"en":"Apollo","ko":"아폴로","aliases":["아폴로","Apollo"],"role":"assassin","complexity":2,"style":"반격과 찌르기 연타로 일대일에 강한 검객형 암살자","tags":["근접","반격","결투"],"laneStrength":"even","spikes":"이타니 로 산을 배우면 체력이 절반 이하인 적을 크게 터뜨릴 수 있습니다. 완벽한 전진 타이밍에 익숙해질수록 피해가 크게 늘어납니다.","strengths":["반격 성공 시 무적이 되고 적을 기절시킴","완벽한 전진으로 이동과 공격을 동시에","궁극기로 적의 행동과 치유를 막음"],"weaknesses":["반격 타이밍을 놓치면 위험해짐","붙어야 해서 원거리 견제에 약함","조작이 까다로워 실수하기 쉬움"],"vsTips":["반격 자세를 잡으면 공격을 멈추고 끝날 때까지 기다리세요","후퇴의 문양으로 빠진 뒤엔 진입 수단이 줄어드니 그때 압박하세요","체력이 절반 아래면 궁극기 베기를 피해 멀리 빠지세요"],"withTips":["궁극기 시간 지연 중엔 피해가 줄어드니 끝난 직후 공격하세요","반격으로 적이 기절하면 바로 따라 들어가세요"],"plan":{"early":"반격으로 상대 공격을 받아치고 짧은 찌르기로 교환하세요.","mid":"완벽한 전진으로 측면에 붙어 혼자 있는 적을 노리세요.","late":"궁극기로 핵심 적을 묶고 체력이 절반 이하일 때 크게 마무리하세요."},"core":["반격으로 공격을 튕겨내면 무적 후 대상에게 돌진 기절","완벽한 전진은 키를 눌렀다 타이밍 맞춰 놓으면 최대 피해","이타니 로 산으로 베어 시간 지연, 끝나면 큰 피해"],"counterItems":["Slowing Hex","Debuff Reducer"],"confidence":"low","abilities":[{"slot":1,"en":"Disengaging Sigil","ko":"후퇴의 문양","desc":"전방에 문양 마법진을 그린 뒤 뒤로 도약합니다. 마법진은 폭발하며 휘말린 적군에게 피해를 입히고 둔화 효과를 적용합니다.","brief":"문양 남기고 후퇴, 폭발 피해·둔화","short":"후퇴·폭발 둔화","tip":"문양 폭발 범위에서 벗어나고 뒤로 빠진 아폴로를 무리해서 쫓지 마세요"},{"slot":2,"en":"Riposte","ko":"반격","desc":"다음 공격을 튕겨낼 준비를 합니다. 튕겨내기에 성공하면 잠시 동안 무적 상태가 된 후, 대상으로 지정한 적군 영웅을 향해 돌진하여 기절시키고 근거리 공격 저항을 감소시킵니다. 능력 2 키를 눌러 대상을 선택합니다.트루퍼 및 중립 유닛의 피해에는 발동하지 않습니다.","brief":"공격 튕겨내면 돌진·기절","short":"튕겨내고 기절","tip":"반격 준비 중엔 쏘지 말고 자세가 풀리길 기다리세요"},{"slot":3,"en":"Flawless Advance","ko":"완벽한 전진","desc":"어느 방향으로든 연속 전진하며, 전방에 관통 찌르기를 가합니다. 능력 키를 길게 눌러 공격 타이밍을 조절할 수 있으며, 길게 누르고 있을수록 더 큰 피해를 입힙니다. 완벽한 타이밍에 공격하면 최대 피해를 입힙니다. 능력 3 키를 눌러 재시전합니다.","brief":"연속 전진하며 관통 찌르기","short":"관통 찌르기","tip":"찌르기 방향을 보고 옆으로 피하세요"},{"slot":4,"en":"Itani Lo Sahn","ko":"이타니 로 산","desc":"힘을 모아 장거리 베기 공격을 가합니다. 적중한 적은 어떤 행동도 할 수 없고 치유를 받을 수 없으며 시간 지연 상태가 됩니다. 지연 상태가 끝나면 막대한 피해를 입히며, 체력이 절반 이하인 적에게는 추가 피해를 입힙니다.시간 지연 중일 때 아폴로는 무적이며, 적군이 입는 피해는 감소합니다 능력 4 혹은 키를 길게 눌러 시전을 지연할 수 있습니다.","brief":"장거리 베기, 행동 불가 후 큰 피해","short":"장거리 베기","tip":"베기 준비 동작이 보이면 사선에서 옆으로 벗어나세요"}]},{"id":78,"en":"Deadman Danny","ko":"데드맨 대니","aliases":["데드맨 대니","Deadman Danny"],"role":"marksman","complexity":2,"style":"제트팩으로 날며 미사일 표식과 충전 사격으로 싸우는 사수","tags":["공중 기동","표식","잡기"],"laneStrength":"even","spikes":"계약 마무리를 배우면 체력이 낮은 적을 붙잡아 끝낼 수 있습니다. 사격 아이템이 쌓이면 표식을 소모하는 충전 사격이 강해집니다.","strengths":["제트팩으로 높은 곳에서 유리하게 싸움","미사일 표식으로 충전 사격 피해를 키움","궁극기로 적을 붙잡아 큰 피해를 줌"],"weaknesses":["급강하로 영웅을 못 맞히면 스스로 기절","공중에 오래 떠 있으면 표적이 되기 쉬움","궁극기를 쓰면 자신도 피해를 받음"],"vsTips":["바닥에 박힌 미사일 줄을 피해 돌아가세요","제트팩이 과열되면 급강하 지점에서 멀리 떨어지세요","궁극기는 대니도 피해를 받으니 체력을 지키면 역전할 수 있어요"],"withTips":["미사일 표식이 붙은 적을 대니가 쏠 수 있게 몰아주세요","급강하로 띄워진 적을 함께 공격하세요"],"plan":{"early":"미사일로 길목에 표식을 깔고 충전 사격으로 표식을 터뜨려 견제하세요.","mid":"제트팩으로 고지대를 잡고 적의 측면을 노리세요.","late":"한타 뒤 체력이 낮은 적을 계약 마무리로 붙잡아 끝내세요."},"core":["키메라 Mk1 비행은 열기 관리, 과열되면 급강하","과열 급강하가 영웅을 못 맞히면 자신이 기절","스트릭스 표식 적에게 충전 사격, 연료 분사로 열기 배출"],"counterItems":["Bullet Resilience","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Strix Salvo","ko":"스트릭스 일제 사격","desc":"지면에 일직선으로 박히는 영혼 미사일을 일제히 발사합니다. 미사일은 일정 시간 후 또는 적군을 감지하면 폭발하여 마법 피해를 입히고 대상에게 표식을 부여합니다.표식이 부여된 적군에게 충전 사격을 맞히면 표식 하나를 소모하여 보너스 마법 피해를 입히고 점차 약해지는 둔화 효과를 적용합니다.길게 누른 채 드래그하여 배치 각도를 정합니다.","brief":"일렬 미사일 매설, 피해·표식","short":"미사일 매설","tip":"미사일이 깔린 선을 밟지 말고 우회하세요"},{"slot":2,"en":"Chimera Mk1","ko":"키메라 Mk1","desc":"점프/오르기 키를 길게 누르면 비행하며 열기를 축적합니다. 최대치에 도달하면 제트팩이 과열되기 시작합니다.과열: 짧은 지연 시간 후 지면으로 급강하합니다. 충돌 시 폭발을 일으켜 피해를 입히고 자신과 주변 적군을 공중으로 띄웁니다. 급강하가 영웅에게 적중하지 못하면 자신이 기절합니다. 능력 2 키를 눌러 원하는 시점에 급강하할 수 있습니다.냉각: 과열 후에는 완전히 냉각될 때까지 제트팩을 사용할 수 없습니다.공중에서도 둔화 효과의 영향을 받습니다. 대니가 사망하면 항상 폭발합니다.","brief":"제트팩 비행, 급강하 피해·띄우기","short":"제트팩 비행","tip":"급강하 착지 지점을 피하면 대니가 스스로 기절합니다"},{"slot":3,"en":"Jettison Fuel","ko":"연료 분사","desc":"연료를 분사하여 지속 무기 피해를 입히고 총탄 저항을 감소시킵니다. 계속 분사하면 거대한 반동 폭발이 일어나 마법 피해를 입히고 자신은 뒤로 밀려납니다.피해를 입히는 동안 제트팩의 열기를 배출합니다.","brief":"연료 지속 피해·총탄 저항 감소","short":"총탄 저항 감소","tip":"연료에 맞으면 총탄 저항이 깎이니 바로 거리를 두세요"},{"slot":4,"en":"Close The Deal","ko":"계약 마무리","desc":"적군을 붙잡고 직접 제품을 시연하기 위해 높이 날아오른 뒤 지면으로 추락합니다.자신과 시연에 참여한 대상은 낙하하는 동안 지속 마법 피해를 입고, 충돌 시 마법 피해를 입습니다. 체력이 50% 미만인 적군에게는 피해가 증가합니다.","brief":"적 붙잡고 날아올라 추락 피해","short":"붙잡아 추락","tip":"체력이 절반 아래일 때는 대니에게 붙잡히지 않게 거리를 유지하세요"}]},{"id":79,"en":"Rem","ko":"렘","aliases":["렘","Rem"],"role":"mystic","complexity":3,"style":"아군에게 붙어 치유하고 낮잠으로 적을 재우는 지원형 마법사","tags":["치유","지원","제어"],"laneStrength":"even","spikes":"낮잠 시간을 배우면 벽 너머의 적까지 묶고 큰 피해를 줄 수 있습니다. 꼬마 도우미 운용에 익숙해질수록 팀의 영혼 수급과 지원이 좋아집니다.","strengths":["동행으로 자신과 아군을 함께 치유함","베개로 적을 강하게 밀쳐냄","궁극기가 벽을 꿰뚫고 이동 능력을 막음"],"weaknesses":["혼자서는 싸우는 힘이 약함","궁극기 기절을 맞으면 아군에게서 떨어짐","붙은 아군이 쓰러지면 함께 위험해짐"],"vsTips":["렘이 붙은 아군을 치유보다 빠르게 몰아치세요","베개에 밀리지 않게 낭떠러지 근처를 피하세요","낮잠 시선에 걸리면 집중이 끝나기 전에 시선 밖으로 벗어나세요"],"withTips":["렘이 붙으면 체력이 회복되니 조금 더 공격적으로 싸우세요","베개에 밀려난 적을 따라가 마무리하세요"],"plan":{"early":"베개로 견제하고 동행으로 아군과 함께 체력을 회복하며 전선을 버티세요.","mid":"꼬마 도우미로 상자와 영혼을 챙기고 싸움이 나면 아군에게 붙으세요.","late":"낮잠 시간으로 여러 적을 묶고 아군에게 붙어 끝까지 치유하세요."},"core":["동행으로 아군에게 붙어 낮잠, 아군 사이를 옮겨 다니며 치유","베개 던지기로 적을 밀쳐내고 적중 시 다른 능력 쿨 감소","꼬마 도우미들로 아군·트루퍼 지원, 낮잠 시간으로 광역 수면"],"counterItems":["Healbane","Debuff Reducer"],"confidence":"low","abilities":[{"slot":1,"en":"Pillow Toss","ko":"베개 던지기","desc":"믿음직한 베개를 던져 마법 피해를 입히고 강한 밀쳐내기 효과를 적용합니다.적중 시 렘의 다른 능력의 쿨다운이 감소합니다.","brief":"베개 투척, 피해·강한 밀쳐내기","short":"강한 밀쳐내기","tip":"베개에 맞으면 크게 밀리니 위험한 지형 근처에 서지 마세요"},{"slot":2,"en":"Tag Along","ko":"동행","desc":"아군에게 점프한 뒤 곁에서 낮잠을 잡니다. 렘과 아군 모두 잃은 체력에 비례하여 즉시 치유되며, 이어서 지속 재생 효과를 얻습니다. 능력 2 키를 눌러 아군 사이를 이동하며, 아군을 치유할 수 있습니다. 이 효과는 아군당 1회만 발동합니다.궁극기에 의해 기절 당하면 렘이 떨어집니다.렘은 아이템을 사용할 수 있으며 자신을 대상으로 하는 시전이 아군 대상으로 시전됩니다.","brief":"아군에 붙어 함께 치유·재생","short":"붙어서 치유","tip":"렘이 붙은 영웅을 먼저 노리거나 궁극기 기절로 떼어내세요"},{"slot":3,"en":"Lil Helpers","ko":"꼬마 도우미들","desc":"도우미에게 도움을 요청합니다. 도우미는 상자를 수집하고, 영혼 슬롯머신을 타격할 수 있습니다. 또한, 이들에게 아군 영웅과 트루퍼를 지원하도록 명령할 수 있습니다.영웅 따라가기: 잠시 동안 마법 저항을 부여하고 점차 사라지는 이동 속도를 부여합니다.트루퍼 따라가기: 치유, 피해 증가, 저항을 부여하고 동행을 사용할 수 있습니다. 주변에 영웅이 없을 경우, 트루퍼 처치로 생성된 영혼은 팀원에게 분배됩니다.동행 중에 시전할 수 있습니다. 누군가를 따라다닌 도우미는 이후 15.1초 동안 낮잠을 잡니다.","brief":"도우미가 상자 수집·아군 지원","short":"상자 수집","tip":"도우미가 붙은 트루퍼는 강해지니 먼저 처리하세요"},{"slot":4,"en":"Naptime","ko":"낮잠 시간","desc":"전방을 주시하여, 벽과 바닥을 꿰뚫어 봅니다. 시선에 걸린 적군은 둔화되고, 대시 거리가 감소하며, 이동 능력을 사용할 수 없습니다.능력 집중이 끝나면 적군은 잠에 들었다가, 깨어날 때 막대한 마법 피해를 입히는 격심한 두통을 겪습니다.","brief":"시선 내 적 둔화 후 수면·큰 피해","short":"수면","tip":"시선은 벽도 통과하니 벽 뒤라고 안심하지 마세요"}]},{"id":80,"en":"Silver","ko":"실버","aliases":["실버","Silver"],"role":"brawler","complexity":1,"style":"올가미로 묶고 늑대로 변신해 몰아치는 근접 싸움꾼","tags":["변신","제어","근접"],"laneStrength":"strong","spikes":"피의 갈망이 쌓여 늑대의 저주가 발동하면 체력과 연사 속도가 크게 오릅니다. 급속 연사로 트루퍼와 중립 유닛을 빠르게 정리해 성장이 빠릅니다.","strengths":["급속 연사로 전선과 정글 정리가 빠름","올가미로 이동 능력과 활력을 막음","변신하면 체력과 연사 속도가 크게 오름"],"weaknesses":["급속 연사 중에는 명중률이 떨어짐","멀리서 견제하는 적에게 약함","변신 전에는 버티는 힘이 평범함"],"vsTips":["올가미를 맞으면 이동기를 못 쓰니 미리 거리를 벌려 두세요","실버가 변신하면 바로 물러나 지속 시간을 버티세요","체력이 낮은 실버는 갈망이 빨리 차니 마무리를 서두르세요"],"withTips":["올가미에 묶인 적을 함께 집중 공격하세요","실버가 변신하면 같이 진입해 싸움을 여세요"],"plan":{"early":"급속 연사로 트루퍼를 빠르게 정리하고 올가미로 적을 묶어 압박하세요.","mid":"중립 유닛을 빠르게 사냥해 성장하고 변신 타이밍에 싸움을 거세요.","late":"늑대로 변신해 적 진형에 뛰어들어 연사로 몰아치세요."},"core":["포박 올가미로 이동기 봉쇄 → 부츠 킥·급속 연사로 마무리","피해를 줄수록 피의 갈망 축적, 가득 차면 늑대로 자동 변신","늑대 형태는 체력·연사 증가, 능력·무기가 바뀌어 근접 돌격"],"counterItems":["Slowing Hex","Bullet Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Slam Fire","ko":"급속 연사","desc":"즉시 총을 재장전합니다. 제한된 발수 동안 보너스 연사 속도를 얻고 대상의 체력에 비례하여 보너스 무기 피해를 입히지만, 명중률이 감소합니다.트루퍼와 중립 유닛에게 보너스 무기 피해를 입힙니다.","brief":"즉시 재장전·연사 증가·체력 비례 피해","short":"재장전·연사 증가","tip":"급속 연사 중엔 명중률이 낮으니 거리를 벌려 피해를 줄이세요"},{"slot":2,"en":"Boot Kick","ko":"부츠 킥","desc":"앞으로 돌진해 처음 맞은 적을 걷어차 잠깐 묶고 근접 피해를 줍니다. 맞은 적에게는 3초 동안 표식이 남고, 표식이 있는 적을 총으로 맞히면 추가 마법 피해를 주며 표식이 사라집니다. 영웅과 오브젝트에만 맞습니다.","brief":"돌진 발차기, 묶기·표식","short":"발차기 묶기","tip":"근접 거리에서 오래 머물지 말고 거리를 유지하세요"},{"slot":3,"en":"Entangling Bola","ko":"포박 올가미","desc":"올가미를 던져 마법 피해를 입힙니다. 또한 둔화 효과를 적용하고 이동 능력이나 활력 사용을 차단합니다.","brief":"올가미 피해·둔화·이동 능력 차단","short":"이동기 차단","tip":"올가미를 피하도록 좌우로 움직이세요"},{"slot":4,"en":"Lycan Curse","ko":"늑대의 저주","desc":"지속 효과: 피해를 입히면 피의 갈망이 쌓이며, 체력이 낮을 때 더 많이 쌓입니다. 피의 갈망이 최대치에 도달하면 늑대의 저주가 자동으로 발동됩니다.활성 효과: 즉시 변신합니다. 최대 체력이 증가하고, 적군 영웅 상대로 중첩되는 연사 속도를 얻습니다. 또한 능력과 무기가 더 흉포한 형태로 바뀝니다.","brief":"늑대 변신, 최대 체력·연사 속도 증가","short":"체력·연사 증가","tip":"변신하면 정면 대결을 피하고 끝날 때까지 시간을 끄세요"}]},{"id":81,"en":"Celeste","ko":"셀레스트","aliases":["셀레스트","Celeste"],"role":"mystic","complexity":2,"style":"빛 광선과 튕기는 구슬로 마법 피해를 쌓아가는 마법사","tags":["마법 피해","중첩","침묵"],"laneStrength":"even","spikes":"광휘의 단검을 영웅에게 맞힐수록 마법 피해가 계속 오릅니다. 찬란한 경이를 배우면 뭉친 적을 한꺼번에 둔화시키고 깎을 수 있습니다.","strengths":["광선을 맞힐수록 마법 피해가 계속 쌓임","빛을 먹는 자로 마법 흡혈을 얻음","프리즘이 깨지면 주변 적을 침묵시킴"],"weaknesses":["광선은 지연이 있어 피하기 쉬움","이동기가 부족해 기습에 약함","중첩이 쌓이기 전엔 화력이 약함"],"vsTips":["하늘에서 광선이 내려오면 바로 범위 밖으로 피하세요","프리즘이 깨지면 침묵이 오니 바로 옆에서 깨지 마세요","섬광에 맞으면 셀레스트가 흡혈하니 바로 물러나세요"],"withTips":["광선이 떨어질 위치로 적을 몰아주세요","구슬로 둔화된 적을 함께 추격하세요"],"plan":{"early":"광선을 꾸준히 맞혀 마법 피해 중첩을 쌓고 섬광으로 체력을 유지하세요.","mid":"뭉친 적에게 광선과 구슬을 맞혀 한타 피해를 키우세요.","late":"쌓인 마법 피해로 후방에서 광선과 구슬을 퍼부으세요."},"core":["빛을 먹는 자로 맞힌 적에게 내 공격마다 추가 마법 피해·흡혈","광휘의 단검을 영웅에게 맞힐수록 마법 피해 중첩 증가","눈부신 속임수 방벽이 깨지면 주변 침묵, 마무리는 찬란한 경이"],"counterItems":["Spirit Resilience","Healbane"],"confidence":"low","abilities":[{"slot":1,"en":"Light Eater","ko":"빛을 먹는 자","desc":"빛의 섬광을 내뿜어 전방 공격 영역의 적을 강타합니다. 섬광에 적중한 적은 셀레스트의 공격을 받을 때 마법 피해를 입으며 셀레스트에게 마법 체력 흡수를 제공합니다.","brief":"전방 섬광, 적중 적 체력 흡수","short":"섬광 흡수","tip":"셀레스트 정면에 서지 말고 섬광 범위를 피하세요"},{"slot":2,"en":"Dazzling Trick","ko":"눈부신 속임수","desc":"보호 프리즘으로 몸을 감쌉니다. 방벽이 파괴되면 주변 적군을 침묵시키고 방벽 수치의 일부만큼 피해를 입힙니다.","brief":"보호 방벽, 깨지면 주변 침묵·피해","short":"방벽·침묵","tip":"프리즘은 거리를 두고 사격해서 깨세요"},{"slot":3,"en":"Radiant Daggers","ko":"광휘의 단검","desc":"하늘에서 빛의 광선을 내려꽂습니다. 잠시 후, 광선이 완전히 형성되면 폭발을 일으키며 범위 내 모든 대상에게 마법 피해를 입힙니다.광선이 적군 영웅에게 적중할 때마다 셀레스트는 마법 피해가 증가하는 중첩 버프를 얻습니다.","brief":"광선 낙하 후 범위 폭발","short":"광선 폭발","tip":"광선이 완성되기 전에 범위를 벗어나세요"},{"slot":4,"en":"Shining Wonder","ko":"찬란한 경이","desc":"치명적인 빛의 구슬을 발사해 마법 피해를 입히고 둔화 효과를 적용하며, 적중 시 대시 거리를 감소시킵니다. 이후 구슬은 범위 내에 적군들에게 튕깁니다. 대상을 찾을 수 없는 경우, 구슬은 잠시 해당 위치에 머물며 계속해서 대상을 찾습니다.대상 지정 시 적군 영웅을 우선합니다.","brief":"튕기는 빛 구슬, 피해·둔화","short":"빛 구슬","tip":"구슬이 영웅을 우선해 튕기니 아군과 너무 붙어 있지 마세요"}]},{"id":84,"en":"Rat King","ko":"랫 킹","aliases":["랫 킹","Rat King"],"role":"brawler","complexity":3,"style":"쥐 떼와 고철 갑옷으로 버티며 아군을 이끄는 근접 싸움꾼","tags":["탱킹","저항 감소","아군 강화"],"laneStrength":"even","spikes":"궁극기 깃발을 배우면 한타에서 아군 전체를 단단하고 빠르게 만듭니다. 체력 아이템이 쌓일수록 고철 갑옷 방벽도 커집니다.","strengths":["갑옷 방벽이 총탄을 공격자에게 반사함","쥐 떼로 적의 총탄 저항을 깎음","깃발로 아군에게 둔화 면역과 피해 감소를 줌"],"weaknesses":["쥐는 대시로 떼어낼 수 있음","고철 수류탄은 근거리 공격으로 쳐낼 수 있음","깃발에서 멀어지면 버프가 사라짐"],"vsTips":["쥐가 붙으면 대시로 바로 떼어내세요","갑옷 방벽이 있을 땐 사격을 줄이고 능력으로 깨세요","수류탄은 근거리 공격으로 쳐내거나 범위를 벗어나세요"],"withTips":["깃발 근처에서 싸워 이동 속도와 피해 감소를 받으세요","쥐가 붙은 적은 총탄 저항이 낮으니 집중 사격하세요"],"plan":{"early":"고철 수류탄과 쥐 떼로 견제하고 갑옷으로 피해를 받아내세요.","mid":"쥐 떼로 저항을 깎은 적을 아군 딜러와 함께 잡으세요.","late":"깃발을 세워 아군과 함께 진입하고 앞에서 피해를 받아내세요."},"core":["쥐 떼를 붙여 지속 피해·총탄 저항 감소 → 집중 사격","쥐왕의 예복 방벽으로 버티며 총탄 일부 반사, 앞장서 진입","궁극기 깃발 근처에서 싸우기: 아군 이속·둔화 면역·피해 감소"],"counterItems":["Spirit Resilience","Debuff Reducer"],"confidence":"low","abilities":[{"slot":1,"en":"Scrap Grenade","ko":"고철 수류탄","desc":"여러 번 폭발하여 총탄 피해를 입히고 둔화 효과를 적용하는 고철 수류탄을 던집니다.근거리 공격으로 수류탄을 쳐낼 수 있습니다.","brief":"다중 폭발 수류탄, 피해·둔화","short":"다중 폭발·둔화","tip":"수류탄이 떨어지면 근거리 공격으로 쳐내세요"},{"slot":2,"en":"Rat Swarm","ko":"쥐 떼","desc":"적군에게 달라붙는 쥐 떼를 불러냅니다. 쥐는 지속 마법 피해를 입히며, 물 때마다 대상의 총탄 저항을 감소시킵니다. 달라붙은 쥐가 많을수록 대상을 무는 속도가 빨라집니다.하나의 적군에 여러 마리의 쥐가 달라붙을 수 있지만, 지상 또는 공중 대시로 쥐를 더 빠르게 떼어낼 수 있습니다.","brief":"쥐 부착, 지속 피해·총탄 저항 감소","short":"쥐 떼","tip":"쥐가 붙으면 지상이나 공중 대시로 떨쳐내세요"},{"slot":3,"en":"Royal Pestments","ko":"쥐왕의 예복","desc":"고철 갑옷을 걸쳐 최대 체력에 비례하는 방벽을 얻습니다. 갑옷이 유지되는 동안 일정 확률로 총탄을 공격자에게 튕겨냅니다.방벽은 저항 효과의 영향을 받지 않습니다.","brief":"체력 비례 방벽·총탄 반사","short":"총탄 반사","tip":"갑옷이 있는 동안엔 총탄이 튕겨오니 능력으로 상대하세요"},{"slot":4,"en":"Rule, Ratannia!","ko":"지배하라, 랫타니아여!","desc":"힘을 모아 랫타니아의 깃발을 소환합니다. 깃발 근처의 모든 아군은 깃발 가까이에 있는 동안 이동 속도가 증가하고, 둔화에 면역이 되며, 받는 피해가 감소합니다.","brief":"깃발 근처 아군 가속·피해 감소","short":"아군 가속 깃발","tip":"깃발 근처에서 싸우지 말고 적을 깃발 밖으로 끌어내세요"}]},{"id":85,"en":"Solomon","ko":"솔로몬","aliases":["솔로몬","Solomon"],"role":"mystic","complexity":1,"style":"체스 말을 배치해 구역을 장악하고 아군을 지키는 마법사","tags":["구역 장악","방벽","이동 불가"],"laneStrength":"even","spikes":"비숍과 룩 업그레이드가 갖춰지면 좁은 길목을 확실하게 장악합니다. 퀸 전개가 준비되면 한타 영향력이 커집니다.","strengths":["비숍으로 오래 남는 위험 구역을 만듦","킹사이드 나이트로 아군에게 방벽을 줌","룩이 벽에 튕겨 예상 밖 각도로 묶음"],"weaknesses":["말을 배치할 시간이 필요해 기습에 약함","넓은 공간에선 구역 장악이 약해짐","말 위치가 읽히면 쉽게 우회당함"],"vsTips":["비숍 주변 대각선 칸을 밟지 마세요","룩은 벽에 튕겨 돌아오니 벽 근처에서 방심하지 마세요","방벽을 받은 아군보다 솔로몬 본체를 노리세요"],"withTips":["나이트로 승격되면 늘어난 활력으로 과감하게 움직이세요","룩에 묶인 적에게 바로 화력을 집중하세요"],"plan":{"early":"비숍을 전선 길목에 두고 룩으로 적을 묶어 견제하세요.","mid":"중요 지점에 비숍을 배치해 구역을 장악하고 아군에게 나이트를 거세요.","late":"말들로 한타 지역을 장악하고 아군 보호와 제어에 집중하세요."},"core":["비숍을 깔아두고 보조 사격 키로 이동, 대각선 칸으로 지역 장악","킹사이드 나이트로 아군(또는 자신)에게 방벽·재배치","룩 배터리로 묶고 퀸 전개로 광역 기절 마무리"],"counterItems":["Spirit Resilience","Debuff Reducer"],"confidence":"low","abilities":[{"slot":1,"en":"Setup Bishop","ko":"비숍 배치","desc":"지정한 위치에 계속 남아 있는 비숍을 생성합니다.이동 ( ): 비숍을 이동시켜 경로상의 적군에게 시간이 지남에 따라 약해지는 둔화 효과를 적용하고 마법 피해를 입힙니다. 잠시 후 비숍을 중심으로 대각선 방향의 칸이 활성화됩니다. 해당 칸을 밟는 적군은 추가 마법 피해를 입습니다.재시전하면 모든 비숍을 회수하고 능력을 종료합니다.","brief":"말 배치, 이동 경로 피해·둔화","short":"경로 피해·둔화","tip":"비숍 이동 경로와 대각선 칸을 피해 움직이세요"},{"slot":2,"en":"Kingside Knight","ko":"킹사이드 나이트","desc":"아군을 나이트로 승격시켜 일정 시간 동안 보너스 활력과 방벽 효과를 부여합니다.자신에게 시전하면 자신을 킹으로 지정해 두 배의 방벽이 부여되지만, 활력은 부여되지 않습니다.이동 ( ): 해당 말을 이동시킵니다. 대상은 착지할 때까지 무적 상태가 됩니다. 자신에게 시전한 경우에는 능력을 다시 사용하여 이동합니다.","brief":"아군 활력·방벽 부여, 이동 시 무적","short":"아군 방벽","tip":"방벽을 받은 적과는 방벽이 사라진 뒤 싸우세요"},{"slot":3,"en":"Rook Battery","ko":"룩 배터리","desc":"두 개의 룩을 전방으로 보내 마법 피해를 입히고 이동 불가 효과를 적용합니다. 룩은 벽에 부딪히면 튕겨서 반대 방향으로 돌진합니다.재시전: 두 개의 룩이 직각으로 갈라져 서로 반대 방향으로 이동합니다.","brief":"룩 돌진, 피해·이동 불가·벽 반사","short":"룩 돌진","tip":"벽에 튕겨 돌아오는 룩까지 계산해 피하세요"},{"slot":4,"en":"Develop Queen","ko":"퀸 전개","desc":"지정한 곳에 퀸을 떨어뜨려 범위 마법 피해를 줍니다. 이어서 퀸 주변의 가로·세로·대각선 칸에 차례로 피해와 기절을 겁니다. 보조 사격(확대)으로 퀸을 다른 곳으로 도약시키면 같은 공격을 반복합니다(기본 2번). 다시 사용하면 퀸을 일찍 거둡니다.","brief":"퀸 낙하 범위 피해, 칸 따라 기절","short":"퀸 기절","tip":"궁극기가 준비된 솔로몬 근처에서는 아군끼리 흩어지세요"}]},{"id":86,"en":"Violet","ko":"바이올렛","aliases":["바이올렛","Violet"],"role":"mystic","complexity":1,"style":"붓과 잉크로 적을 묶고 스케치를 모아 성장하는 마법사","tags":["성장형","침묵","시야 차단"],"laneStrength":"even","spikes":"정물화로 스케치를 모을수록 능력치가 영구적으로 오릅니다. 추상 풍경화를 배우면 한타 지역을 잉크로 덮어 적을 침묵시킬 수 있습니다.","strengths":["스케치를 모을수록 영구적으로 강해짐","붓 궤적으로 적을 둔화시키고 아군을 도움","궁극기로 적을 가두고 나가면 침묵시킴"],"weaknesses":["정물화는 대상을 계속 바라봐야 함","스케치를 못 모으면 성장이 더딤","이동기가 부족해 기습에 약함"],"vsTips":["정물화가 걸리면 엄폐물 뒤로 숨어 시선을 끊으세요","떨어진 스케치를 바이올렛이 줍지 못하게 압박하세요","잉크 밖으로 나가면 침묵에 걸리니 중요한 능력을 쓴 뒤 나가세요"],"withTips":["붓 궤적 위에서 활주하면 더 멀리 이동할 수 있어요","잉크 안의 적은 위치가 드러나니 함께 집중 공격하세요"],"plan":{"early":"정물화로 적 영웅을 노려 스케치를 모으고 붓으로 견제하세요.","mid":"싸움마다 스케치를 챙겨 능력치를 꾸준히 올리세요.","late":"추상 풍경화로 적을 가두고 아군 마력 버프로 한타를 이기세요."},"core":["살아있는 잉크: 다음 총탄 3발을 조종, 영웅 적중 시 쿨 감소","다른 능력을 쓰면 몰입의 경지 쿨 초기화 → 붓으로 이동·견제","정물화 스케치를 완성·수집하면 능력치가 영구 성장"],"counterItems":["Debuff Reducer","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Living Ink","ko":"살아있는 잉크","desc":"충전 2회. 강화: 다음 총알 3발이 살아 움직여, 날아가는 동안 직접 조종할 수 있고 총알 피해와 작은 범위 마법 피해가 늘어납니다. 영웅을 맞힐 때마다 모든 능력 쿨다운이 줄어듭니다. 그리기(보조 사격): 투사체와 캐릭터를 막는 잉크 벽을 그립니다. 20초 동안 남습니다.","brief":"조종 총알 강화·잉크 벽 그리기","short":"총알 강화·벽","tip":"바이올렛과의 정면 교전은 짧게 끊으세요"},{"slot":2,"en":"Flow State","ko":"몰입의 경지","desc":"궤적을 남기는 붓을 전방으로 보냅니다. 궤적은 아군의 활주 거리를 증가시키고, 붓은 통과하는 적군에게 점차 약해지는 둔화 효과를 부여하고 마법 피해를 입힙니다. 붓이 멀리 이동할수록 피해가 증가합니다.능력을 다시 사용하면 능력을 조기에 종료하고, 붓을 앞으로 튕겨 더 넓은 범위에 마법 피해를 입힙니다.","brief":"붓 발사 피해·둔화, 아군 활주 증가","short":"붓·둔화","tip":"붓이 지나가는 궤적에서 벗어나 둔화를 피하세요"},{"slot":3,"en":"Still Life","ko":"정물화","desc":"영웅 하나를 그림의 모델로 지정하고, 대상을 바라보는 동안 지속 마법 피해를 줍니다.스케치를 완성하면 대상에게 추가 마법 피해를 입히고 기절 효과를 적용하며, 수집할 수 있는 스케치를 떨어뜨립니다.스케치를 수집할 때마다 스케치에 그려진 영웅에 따라 능력치가 영구적으로 증가합니다.","brief":"응시 지속 피해, 완성 시 기절","short":"응시 기절","tip":"벽 뒤로 숨어 시선을 끊으면 스케치 완성을 막을 수 있어요"},{"slot":4,"en":"Abstract Landscape","ko":"추상 풍경화","desc":"원형으로 시야를 차단하는 잉크를 펼치고 아군에게 마력을 부여합니다.내부에 있는 적군은 위치가 드러납니다. 적군이 잉크 밖으로 나가면 마법 피해를 입고, 침묵 및 둔화 효과를 받으며, 그 과정에서 잉크는 파괴됩니다.","brief":"시야 차단 잉크, 나가는 적 침묵·둔화","short":"시야 차단·침묵","tip":"잉크를 나가기 전에 필요한 능력을 먼저 쓰세요"}]},{"id":87,"en":"Nurse Harrow","ko":"너스 해로우","aliases":["너스 해로우","Nurse Harrow"],"role":"marksman","complexity":1,"style":"거머리와 치유 주사기로 싸우며 아군을 살리는 사수형 지원가","tags":["치유","지속 피해","공포"],"laneStrength":"even","spikes":"거머리를 많이 모을수록 주사기 충전과 공포 지속 시간이 늘어납니다. 도사린 공포를 배우면 한타에서 적을 쫓아낼 수 있습니다.","strengths":["주사기 탄창으로 아군을 치유함","거머리가 적의 강화 효과를 줄여줌","궁극기로 바라보는 적을 공포에 빠뜨림"],"weaknesses":["증기 효과가 끝나면 모든 동작이 느려짐","치유에 집중하면 딜이 줄어듦","등을 돌린 적에겐 궁극기 피해가 약함"],"vsTips":["해로우가 가방을 열면 등을 돌려 공포 축적을 막으세요","증기 효과가 끝나 느려진 대상을 노려 반격하세요","거머리가 붙어 있을 땐 중요한 강화 효과를 아껴 두세요"],"withTips":["해로우의 주사기에 맞을 수 있게 시야 안에서 싸우세요","증기를 받으면 빠를 때 몰아치고 끝나기 전에 빠지세요"],"plan":{"early":"거머리로 적을 깎고 주사기로 아군 체력을 채워 전선을 버티세요.","mid":"싸움 직전에 아군에게 증기를 걸어 순간 화력을 끌어올리세요.","late":"도사린 공포로 적을 흩어 놓고 주사기로 아군을 살리세요."},"core":["구원의 바늘로 탄창을 치유 주사기로 바꿔 아군 치료","거머리 요법 거머리를 수집할수록 바늘 충전·공포 시간 강화","도사린 공포: 나를 보는 적은 이동기 봉쇄 후 공포로 도주"],"counterItems":["Healbane","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Leech Therapy","ko":"거머리 요법","desc":"거머리가 든 병을 던집니다. 거머리는 적군에게 달라붙어 지속 마법 피해를 입히고 적군의 강화 효과 지속 시간을 먹어치웁니다.","brief":"거머리 지속 피해·강화 효과 단축","short":"강화 효과 단축","tip":"거머리가 붙으면 강화 효과가 빨리 끝나니 버프는 나중에 쓰세요"},{"slot":2,"en":"Wretched Vapors","ko":"음산한 증기","desc":"작은 병을 열어 자신이나 아군을 대상으로 초자연적인 증기를 내뿜습니다. 대상은 일시적으로 활기를 얻은 뒤 쇠약해집니다.망령의 활기: 효과가 지속되는 동안 모든 동작의 속도가 증가하고, 입는 모든 피해가 일시적으로 지연되며 망령이 나타납니다.망령의 쇠약: 증기 효과가 끝나면 모든 동작 속도가 감소하고, 남아 있는 망령이 지연된 피해에 추가 피해를 더해 대상에게 입힙니다.받는 치유는 망령을 제거하는 데 우선 사용되며, 망령이 제거되면 피해를 입히지 않습니다.","brief":"아군 가속·피해 지연, 이후 쇠약","short":"가속·피해 지연","tip":"증기가 끝난 대상은 느려지니 그때 공격하세요"},{"slot":3,"en":"Healing Needles","ko":"구원의 바늘","desc":"아군을 치유하는 주사기로 무기의 탄창을 가득 채웁니다. 피해를 입히면 충전량이 회복되며, 수집한 거머리 하나당 충전량이 서서히 회복됩니다.재장전 시 충전 1회를 소모하여 탄창을 새로 채웁니다.재시전하면 주사기를 집어넣습니다. 남은 탄약에 해당하는 충전량을 돌려받습니다.","brief":"탄창을 아군 치유 주사기로 장전","short":"치유 주사기","tip":"주사기로 치유받는 적보다 해로우를 먼저 노리세요"},{"slot":4,"en":"Lurking Terrors","ko":"도사린 공포","desc":"가방을 열어 그 안에 도사린 공포를 드러내고, 전방의 적군에게 지속 마법 피해를 입힙니다. 해로우를 바라보는 적군은 공포가 축적되며 활력 및 이동 능력을 사용할 수 없습니다. 공포가 최대치에 도달하면, 대상은 공포에 질려 해로우에게서 달아납니다.수집한 거머리 하나당 공포 지속 시간이 증가합니다.해로우를 등진 적군은 공포 상태가 아닐 경우 피해의 50%만 입습니다.","brief":"전방 지속 피해, 바라보는 적 공포","short":"바라보면 공포","tip":"가방이 열리면 해로우를 바라보지 말고 등을 돌려 벗어나세요"}]},{"id":88,"en":"Baba","ko":"바바","aliases":["바바","Baba"],"role":"mystic","complexity":1,"style":"마력을 훔치고 차와 비둘기로 적을 괴롭히는 마법사","tags":["마력 강탈","침묵","변신 저주"],"laneStrength":"even","spikes":"실타래로 마력을 훔친 상태에서는 총탄 마법 피해가 크게 오릅니다. 모이 뿌리기를 배우면 뭉친 적을 비둘기로 만들어 한타를 열 수 있습니다.","strengths":["실타래로 적의 마력을 훔쳐 강해짐","차 효과로 아군 보호와 침묵을 모두 함","궁극기로 여러 적을 비둘기로 만듦"],"weaknesses":["차 효과 타이밍을 맞추기 어려움","궁극기는 전방 범위라 피하면 효과가 약함","실타래가 빗나가면 화력이 줄어듦"],"vsTips":["실타래 경로에서 벗어나 마력을 빼앗기지 마세요","빵이 쌓일수록 위험하니 모이 뿌리기 범위를 빨리 벗어나세요","다리가 길어지면 발차기와 내려찍기에 대비해 거리를 두세요"],"withTips":["바바가 던지는 방벽 차를 받을 수 있게 가까이 붙으세요","비둘기로 변한 적을 바로 집중 공격하세요"],"plan":{"early":"실타래로 적의 마력을 훔쳐 총탄 피해를 높이고 견제하세요.","mid":"상황에 맞는 차를 골라 아군을 지키거나 적을 침묵시키세요.","late":"모이 뿌리기로 여러 적을 비둘기로 만든 뒤 아군과 함께 몰아치세요."},"core":["마력 강탈 실타래로 마력을 훔치고, 보유 중엔 총탄 추가 피해","키다리 할머니로 이속·점프 강화, 발차기·내려찍기로 최전선","바바의 차는 방벽→침묵→화상 순환, 원하는 효과일 때 투척"],"counterItems":["Debuff Reducer","Spirit Resilience"],"confidence":"low","abilities":[{"slot":1,"en":"Threadsap","ko":"마력 강탈 실타래","desc":"조준점을 따라 움직이는 헝클어진 실을 엮어 경로를 따라 터뜨립니다. 적군에게 마법 피해를 입히고 마력을 훔칩니다. 훔친 마력은 바바에게 더 높은 효율로 적용됩니다.훔친 마력을 보유하는 동안 바바의 모든 탄환이 보너스 마법 피해를 입힙니다.","brief":"실 경로 폭발, 피해·마력 강탈","short":"실 폭발","tip":"실이 터지기 전에 경로에서 비켜서세요"},{"slot":2,"en":"Granny Long Legs","ko":"키다리 할머니","desc":"벤치 다리가 길어져 추가 이동 속도를 얻고 더 높이 점프할 수 있습니다. 약화 효과 저항과 근거리 공격 저항이 증가합니다.약한 근거리 공격: 적군을 밀쳐내는 발차기를 합니다.강한 근거리 공격: 지면을 내려찍어 들어올리기 및 둔화 효과를 적용하고 마법 피해를 입힙니다. 웅크리기/활주 키를 길게 눌러 힘을 모으고, 키에서 손을 떼면 높이 점프합니다.","brief":"다리 늘려 이동 속도·점프·저항 증가","short":"이속·점프 증가","tip":"다리가 길어진 바바에게 가까이 붙지 마세요"},{"slot":3,"en":"Baba's Brew","ko":"바바의 차","desc":"마법의 차를 우립니다. 차를 우리는 동안 방벽 효과, 침묵 효과, 뜨거운 화상 효과가 차례로 반복됩니다. 화상은 지속 마법 피해를 입히고 마법 저항을 감소시킵니다. 차를 던지면 해당 효과가 범위 내에 적용됩니다. 키를 누르면 차 우리기를 일시 정지하거나 재개합니다.","brief":"방벽·침묵·화상 차 투척","short":"침묵·화상 차","tip":"차가 떨어진 범위를 벗어나 침묵과 화상을 피하세요"},{"slot":4,"en":"Feed The Birds","ko":"모이 뿌리기","desc":"전방에 있는 대상들에게 빵을 뿌려 중첩되는 둔화 효과를 적용합니다.정신 집중이 끝나면 비둘기 떼가 각 대상을 공격해 마법 피해를 입히고 저주를 걸어 비둘기로 변신시킵니다. 대상에게 묻은 빵이 많을수록 대상이 입는 피해와 변신 지속 시간이 증가합니다.","brief":"빵 둔화 후 비둘기 변신·피해","short":"비둘기 변신","tip":"빵이 쌓이기 전에 바바 정면에서 벗어나세요"}]}];
